# SYSTEM CONSOLE -- SETTLEMENT LEAVES EXPENSE CLAIM (23 Nov 2026, the user: "lets create a new
# doctype for the settlement cuz there will be a confusion and issue if we use the same for both").
# After this, Expense Claim holds ONLY the field TA/DA (and Field Cab); settlement never touches it.
# Paste into ERP > System Console (type Python), logged in as Administrator. Prod (UAT the same).
#   1) DRY = True, "Commit" unticked: only prints what it would do.
#   2) DRY = False, tick "Commit", Execute.          Safe to re-run.
#
# What it does:
#   1. DocType "Settlement Expense" (SE-#####): one record per settlement bill -- date, what for,
#      amount, bill photo (+ payment proof for a handwritten bill), status Checking -> Checked ->
#      In Approval -> Verified -> Paid, the check's score, and how it was booked. Reps and
#      approvers get NO permission on it: the Settlement API writes it, and shares each bill
#      (read only) with its approvers when it is sent. System Manager edits; Accounts / HR read.
#   2. Server Script "Settlement API" (method settlement) replaced
#      <- share/src/app/expense-claims/server/settlement_api.py
#      New actions bills / add_bill / remove_bill / score; send_bills, approve, reject and
#      withdraw now work on Settlement Expense. The CEO's approval books the bill as ONE
#      Journal Entry (was a submitted Expense Claim): Dr the expense account for its kind,
#      Cr the employee's unspent cash advances first (against the advance -- the advance shows
#      that part as "Returned"), the rest Cr 2120 Employee Expense Payable (party = Employee).
#   3. Server Script "Settlement Accounts API" replaced (the Settlement Payments page): what is
#      owed comes from the bills' Journal Entries; paying makes one Bank Entry per employee against
#      them (ERPNext takes no Payment Entry against a Journal Entry owed to an employee) and marks
#      the bills Paid; cash advances are still paid by Payment Entry.   <- settlement_accounts_api.py
#   Tested end to end on UAT on 23 Nov 2026 with test logins (rep -> manager -> CEO -> booked ->
#   paid, sent back and sent again, the advance used first, photos shared with the approvers).
#   4. Report "Settlement To Pay": the same, ref doctype Settlement Expense.  <- settlement_to_pay_report.py
#   5. Web Page "settlement-payments": a bill links to its Settlement Expense and Journal Entry.
#      <- settlement_payments_page.html / .js / .css
#   6. Server Script "Bill Fingerprint API": a refused settlement bill is commented on the bill.
#   7. CLEAN_TEST = True only: the two settlement TEST claims (Vignesh K) are removed --
#      HR-EXP-2026-00026 (Rs 485, booked from SR-00003) cancelled and deleted, its GL reversed;
#      HR-EXP-2026-00025 (the running draft, Rs 6,021) deleted. Look at them first.
# Not changed: the field TA/DA, Settlement Request / Batch, the escalation, cash requests
# (Employee Advance). The old Expense Claim scripts for the "running claim" stay, unused.

DRY = True
CLEAN_TEST = False
W = "WOULD " if DRY else ""
DT = {'doctype': 'DocType', 'name': 'Settlement Expense', 'module': 'Elbrit Mod', 'custom': 1, 'istable': 0, 'autoname': 'SE-.#####', 'naming_rule': 'Expression', 'title_field': 'title', 'sort_field': 'creation', 'sort_order': 'DESC', 'track_changes': 1, 'description': "One settlement bill a person paid for the company (hotel, cab, fuel...). Added from the app through the Settlement API only; goes up the reporting line as a Settlement Request; the CEO's approval books it as a Journal Entry. Kept apart from Expense Claim, which holds only the field TA/DA.", 'fields': [{'fieldname': 'employee', 'label': 'Employee', 'fieldtype': 'Link', 'options': 'Employee', 'reqd': 1, 'in_list_view': 1, 'in_standard_filter': 1, 'search_index': 1}, {'fieldname': 'employee_name', 'label': 'Employee Name', 'fieldtype': 'Data', 'read_only': 1, 'fetch_from': 'employee.employee_name', 'in_list_view': 1}, {'fieldname': 'user', 'label': 'Added By', 'fieldtype': 'Link', 'options': 'User', 'read_only': 1}, {'fieldname': 'status', 'label': 'Status', 'fieldtype': 'Select', 'options': 'Checking\nChecked\nIn Approval\nVerified\nPaid', 'default': 'Checking', 'in_list_view': 1, 'in_standard_filter': 1, 'search_index': 1, 'read_only': 1}, {'fieldname': 'column_break_a', 'fieldtype': 'Column Break'}, {'fieldname': 'bill_date', 'label': 'Bill Date', 'fieldtype': 'Date', 'reqd': 1, 'in_list_view': 1}, {'fieldname': 'title', 'label': 'What For', 'fieldtype': 'Data', 'reqd': 1}, {'fieldname': 'amount', 'label': 'Amount', 'fieldtype': 'Currency', 'reqd': 1, 'in_list_view': 1, 'non_negative': 1}, {'fieldname': 'bill_section', 'label': 'Bill', 'fieldtype': 'Section Break'}, {'fieldname': 'bill', 'label': 'Bill Photo', 'fieldtype': 'Attach'}, {'fieldname': 'proof', 'label': 'Payment Proof', 'fieldtype': 'Attach', 'description': 'For a handwritten bill: the UPI / card slip'}, {'fieldname': 'hand_note', 'label': 'Handwritten Bill Note', 'fieldtype': 'Small Text', 'description': 'Why only a handwritten bill, and how it was paid'}, {'fieldname': 'column_break_b', 'fieldtype': 'Column Break'}, {'fieldname': 'settlement', 'label': 'Settlement Request', 'fieldtype': 'Link', 'options': 'Settlement Request', 'read_only': 1, 'search_index': 1}, {'fieldname': 'review_note', 'label': 'Sent Back Because', 'fieldtype': 'Small Text', 'read_only': 1}, {'fieldname': 'check_section', 'label': 'Bill check', 'fieldtype': 'Section Break', 'collapsible': 1}, {'fieldname': 'ai_score', 'label': 'Score', 'fieldtype': 'Percent', 'read_only': 1}, {'fieldname': 'ai_risk', 'label': 'Risk', 'fieldtype': 'Data', 'read_only': 1}, {'fieldname': 'ai_reason', 'label': 'Check Result', 'fieldtype': 'Small Text', 'read_only': 1}, {'fieldname': 'column_break_c', 'fieldtype': 'Column Break'}, {'fieldname': 'read_amount', 'label': 'Amount On Bill', 'fieldtype': 'Currency', 'read_only': 1}, {'fieldname': 'read_date', 'label': 'Date On Bill', 'fieldtype': 'Date', 'read_only': 1}, {'fieldname': 'read_vendor', 'label': 'Vendor On Bill', 'fieldtype': 'Data', 'read_only': 1}, {'fieldname': 'bill_meta', 'label': 'Bill Read (JSON)', 'fieldtype': 'Long Text', 'read_only': 1, 'hidden': 1}, {'fieldname': 'accounts_section', 'label': 'Accounts', 'fieldtype': 'Section Break', 'collapsible': 1}, {'fieldname': 'expense_account', 'label': 'Expense Account', 'fieldtype': 'Link', 'options': 'Account', 'read_only': 1}, {'fieldname': 'journal_entry', 'label': 'Booked As', 'fieldtype': 'Link', 'options': 'Journal Entry', 'read_only': 1, 'search_index': 1}, {'fieldname': 'column_break_d', 'fieldtype': 'Column Break'}, {'fieldname': 'from_advance', 'label': 'Covered By Cash Advance', 'fieldtype': 'Currency', 'read_only': 1}, {'fieldname': 'payable', 'label': 'Owed To The Employee', 'fieldtype': 'Currency', 'read_only': 1}], 'permissions': [{'role': 'System Manager', 'read': 1, 'write': 1, 'create': 1, 'delete': 1, 'report': 1, 'export': 1, 'share': 1, 'submit': 0, 'cancel': 0, 'amend': 0, 'import': 0, 'print': 0, 'email': 0, 'if_owner': 0, 'select': 0, 'permlevel': 0}, {'role': 'Accounts Manager', 'read': 1, 'write': 0, 'create': 0, 'delete': 0, 'report': 1, 'export': 1, 'share': 0, 'submit': 0, 'cancel': 0, 'amend': 0, 'import': 0, 'print': 0, 'email': 0, 'if_owner': 0, 'select': 0, 'permlevel': 0}, {'role': 'Accounts User', 'read': 1, 'write': 0, 'create': 0, 'delete': 0, 'report': 1, 'export': 1, 'share': 0, 'submit': 0, 'cancel': 0, 'amend': 0, 'import': 0, 'print': 0, 'email': 0, 'if_owner': 0, 'select': 0, 'permlevel': 0}, {'role': 'HR Manager', 'read': 1, 'write': 0, 'create': 0, 'delete': 0, 'report': 1, 'export': 1, 'share': 0, 'submit': 0, 'cancel': 0, 'amend': 0, 'import': 0, 'print': 0, 'email': 0, 'if_owner': 0, 'select': 0, 'permlevel': 0}]}
API_SRC = '# Server Script "Settlement API" -- type API, method settlement (16 Nov 2026).\n# Settlement approval: a request goes up the requester\'s reporting line --\n# BE > ABM > RBM > SM/ZSM > GM > CEO -- one approver at a time.\n#\n# THE CEO GETS BATCHES (18 Nov 2026, management): the approver right before\n# the CEO (the GM; the SM where no GM is above) sends the bills they approve\n# to the CEO as ONE BATCH per send (Settlement Batch, SB-#####). The CEO\n# approves the batch -- or sends single bills back with a reason, the rest\n# approved. The CEO\'s approval is final: the bills are booked in the ledger\n# at once, and Accounts pays them with no further approval (Settlement Pay\n# API). A request that reaches the CEO any other way (a GM\'s own bill, one\n# sent again to a CEO who rejected it) gets a batch of its own. Every action goes through here (reps and approvers have\n# no DocType permission on Settlement Request), with the caller\'s own token.\n#\n#   SETTLEMENT HAS ITS OWN DOCTYPE (23 Nov 2026, the user: "there will be a\n#   confusion and issue if we use the same for both") -- nothing here touches\n#   Expense Claim any more; Expense Claim holds only the field TA/DA. Each bill\n#   is a Settlement Expense (SE-#####), written only through this script\n#   (reps have no DocType permission on it):\n#     Checking -> Checked (scored by the bill check) -> In Approval (sent) ->\n#     Verified (the CEO approved; booked) -> Paid (Accounts paid it)\n#   A sent-back bill is Checked again with the reason (review_note).\n#\n#   A BILLS request: ONE bill (16 Nov 2026). "Send" makes one request per\n#   unsent bill, each with its own chain, so every bill has its own status and\n#   its own Settlement Request link. The bill keeps its AI score. A CASH\n#   request: an Employee Advance (draft) asked for; CEO approval -> the request\n#   is Verified.\n#\n#   BOOKED AT THE CEO\'S APPROVAL, when BOOK and the accounts exist:\n#     a bill  -> ONE submitted Journal Entry (23 Nov 2026; was an Expense\n#                Claim): Dr the expense account for its kind (hotel 5229,\n#                travel 5228, food 5211, fuel 5230, else 5309); Cr the\n#                employee\'s unspent cash advances first ("Employee Expense\n#                Advances", party = the Employee, against the advance -- the\n#                advance shows that part under "Returned"), the rest Cr 2120\n#                Employee Expense Payable, party = the Employee. -> the bill\'s\n#                journal_entry, from_advance, payable\n#     cash    -> the Employee Advance submitted on "Employee Expense\n#                Advances"; unspent cash is paid back by the employee to the\n#                bank (no salary recovery)\n#   A booking that fails stops the approval too (nothing half done): the CEO\n#   sees why. Accounts then pays what is owed (Settlement Accounts API).\n#   A REJECT, at any step, needs a reason: the request goes back to the rep\n#   (bills to "Checked" with the reason, the advance draft deleted); they fix\n#   and send again. SENT AGAIN (17 Nov 2026): back to whoever rejected it --\n#   the steps approved before stay approved ("Approved before (SR-x)") -- as\n#   long as the bill\'s photo is the same and its amount is not higher; else\n#   from the first approver. resent_from names the rejected request.\n#\n#   NOTHING GETS STUCK (17 Nov 2026), sweep(): a step is SKIPPED when its\n#   approver is no longer active (left, or login disabled) or on approved\n#   leave today, and MOVES UP one level after 2 working days (Sundays not\n#   counted) with no action -- the approver is told -- except a bill read as\n#   High risk (score under 70), which waits. It STOPS AT SM / ZSM (the user,\n#   17 Nov 2026): nothing is ever moved on to a GM or the CEO -- a step whose\n#   next approver is GM / CEO waits, and so does the SM / ZSM step itself.\n#   Runs when a request is sent, after each approval, and hourly\n#   (Server Script "Settlement Escalation", the same sweep()).\n#\n#   GET  action=mine                         the caller\'s requests + their chain\n#   GET  action=bills        [names=a,b]     the caller\'s own bills (Settlement Expense), newest first\n#   POST action=add_bill     bill_date, title, amount, bill (file_url), [proof, hand_note]\n#                                            a new bill; the photos are the caller\'s own\n#                                            unattached private Files, attached here\n#   POST action=remove_bill  name            own, not sent (Checking / Checked)\n#   POST action=score        name, score, reason, amount, bill, [read_amount, read_date,\n#                            read_vendor, meta]   the bill check only (SCORERS): -> Checked\n#   POST action=send_bills   [rows=a,b]      every checked, unsent bill (or just those), one request each\n#   POST action=send_cash    amount, purpose\n#   POST action=withdraw     name            own, while nobody has decided yet\n#   GET  action=queue                        waiting on me / my team / decided by me\n#                                            (overview: IT department, System Manager)\n#   POST action=decide       name, decision (Approve | Reject), note\n#   POST action=approve_many names=a,b       approve them all; those that reach the CEO go as ONE batch\n#   GET  action=ceo_batches                  the CEO\'s batches (waiting, and the last 30 days)\n#   POST action=decide_batch name            the CEO approves what is still waiting in a batch\n#\n# The chain: Employee.reports_to from the requester up, skipping anyone not\n# Active, with no enabled login, or a "Vacant" placeholder, until the CEO. A\n# line that never reaches the CEO gets the CEO added last: the CEO always\n# decides last, on a batch.\n#\n# safe_exec: no import, no .format(), no set literals, no tuple unpacking,\n# no underscore-prefixed names, no frappe.parse_json -- the chain and the\n# bills are child tables (Settlement Step, Settlement Bill), not JSON.\n\nCEO_USER = "ceo@elbrit.org"\nCEO_DESIGNATION = "Chief Executive Officer"\nOVERVIEW_DEPARTMENTS = ["IT - ELPL"]\nOVERVIEW_ROLES = ["System Manager"]\nLEVELS = ["BE", "ABM", "RBM", "SRBM", "DEPUTY RBM", "SM", "ZSM", "GM"]\n# the logins the app\'s bill check scores with (ERP_AI_CHECKER_TOKEN) -- as in\n# the Expense Claim AI Guard\nSCORERS = ["Administrator", "it@elbrit.org"]\n# Booking (17 Nov 2026) -- the user\'s decisions: cost center Main, one payable\n# account with the Employee as party, advances on their own account.\nBOOK = True\nBOOKING = {\n    "company": "Elbrit Lifesciences Private Limited",\n    "payable": "2120 - Employee Expense Payable - ELPL",\n    "advance": "Employee Expense Advances - ELPL",\n    "cost_center": "Main - ELPL",\n    "other": "5309 - Other Employee Expenditure - ELPL",\n    # first match wins, on the bill\'s title ("Hotel bill", "Cab fare", ...)\n    "kinds": [\n        {"account": "5229 - Accomodation Expenditure - ELPL", "words": ["hotel", "lodge", "lodging", "stay", "room", "accommodation", "accomodation", "resort", "guest house", "inn"]},\n        {"account": "5230 - Fuel Expenditure - ELPL", "words": ["fuel", "petrol", "diesel", "cng"]},\n        {"account": "5211 - Food Expenditure - ELPL", "words": ["food", "meal", "restaurant", "lunch", "dinner", "breakfast", "snack", "tea", "coffee", "sweet"]},\n        {"account": "5228 - Travel Expenditure - ELPL", "words": ["cab", "taxi", "uber", "ola", "rapido", "auto", "train", "rail", "irctc", "bus", "flight", "air", "ticket", "travel", "toll", "parking", "metro"]},\n    ],\n}\n\n\ndef level_of(seat, designation, user, ceo_user, ceo_designation, levels):\n    # "ABM2-AURA-CO-SAL" -> ABM; the CEO -> CEO; a back-office seat -> its designation\n    if user == ceo_user or designation == ceo_designation:\n        return "CEO"\n    head = str(seat or "").split("-")[0]\n    g = ""\n    for ch in head:\n        if not ch.isdigit():\n            g = g + ch\n    g = g.strip().upper()\n    if g in levels:\n        return g\n    return str(designation or g or "Approver")\n\n\ndef chain_of(emp_name, ceo_user, ceo_designation, levels):\n    # [{user, name, level}] up the reporting line, ending with the CEO\n    out = []\n    seen = {}\n    cur = frappe.db.get_value("Employee", emp_name, "reports_to")\n    hops = 0\n    ceo = False\n    while cur and hops < 15 and not ceo:\n        hops = hops + 1\n        if seen.get(cur):\n            break\n        seen[cur] = 1\n        m = frappe.db.get_value("Employee", cur, ["name", "employee_name", "user_id", "status", "custom_role_profile", "designation", "reports_to"], as_dict=True)\n        if not m:\n            break\n        live = m.status == "Active" and m.user_id and str(m.employee_name or "")[:6].lower() != "vacant" and frappe.db.get_value("User", m.user_id, "enabled")\n        if live:\n            lv = level_of(m.custom_role_profile, m.designation, m.user_id, ceo_user, ceo_designation, levels)\n            out.append({"user": m.user_id, "name": m.employee_name, "level": lv})\n            if lv == "CEO":\n                ceo = True\n        cur = m.reports_to\n    if not ceo:\n        name = frappe.db.get_value("Employee", {"user_id": ceo_user, "status": "Active"}, "employee_name") or "CEO"\n        out.append({"user": ceo_user, "name": name, "level": "CEO"})\n    return out\n\n\ndef shape(d):\n    steps = []\n    for s in d.steps or []:\n        steps.append({"user": s.user, "name": s.approver_name, "level": s.level, "decision": s.decision or "",\n                      "at": str(s.decided_on or ""), "note": s.note or ""})\n    bills = []\n    for b in d.bills or []:\n        bills.append({"row": b.row, "date": str(b.bill_date or ""), "title": b.title, "amount": b.amount,\n                      "bill": b.bill or "", "score": b.ai_score, "risk": b.ai_risk or "", "reason": b.ai_reason or ""})\n    # the requester\'s HQ = their seat\'s territory (17 Nov 2026: the approvers\'\n    # list goes HQ > employee), "HQ-Trichy" -> "Trichy"\n    # and the TEAM = the seat\'s department (18 Nov 2026: SM, GM and the CEO\n    # see Team > employee): Role Profile.custom_department; an SM-type seat\n    # lists several (custom_departments) -> the first; none -> the\n    # Employee\'s own. "Elbrit Trichy - ELPL" -> "Elbrit Trichy"\n    hq = ""\n    team = ""\n    seat = frappe.db.get_value("Employee", d.employee, "custom_role_profile", cache=True)\n    if seat:\n        rp = frappe.db.get_value("Role Profile", seat, ["custom_territory", "custom_department"], as_dict=True) or {}\n        hq = str(rp.get("custom_territory") or "")\n        team = str(rp.get("custom_department") or "")\n        if not team:\n            team = str(frappe.db.get_value("Department Multiselect", {"parent": seat, "parenttype": "Role Profile", "parentfield": "custom_departments"},\n                                           "department", order_by="idx asc") or "")\n    if not team:\n        team = str(frappe.db.get_value("Employee", d.employee, "department", cache=True) or "")\n    if hq[:3].upper() == "HQ-":\n        hq = hq[3:]\n    if team[-7:] == " - ELPL":\n        team = team[:-7]\n    resent = None\n    if d.get("resent_from"):\n        pv = frappe.db.get_value("Settlement Request", d.resent_from, ["note", "decided_by"], as_dict=True)\n        if pv:\n            resent = {"from": d.resent_from, "note": pv.note or "",\n                      "by": str(frappe.db.get_value("User", pv.decided_by, "full_name") or pv.decided_by or "")}\n    booked = None\n    if d.kind == "Bills" and d.status == "Approved":\n        # the bill\'s Journal Entry: what of it was owed to the employee, and\n        # what of that is still unpaid\n        for b in d.bills or []:\n            se = frappe.db.get_value("Settlement Expense", b.row, ["journal_entry", "payable", "from_advance", "status"], as_dict=True)\n            if se and se.journal_entry:\n                left = outstanding(se.journal_entry, d.employee)\n                booked = {"entry": se.journal_entry, "status": "Paid" if left < 0.5 else "Unpaid", "due": se.payable,\n                          "advance": se.from_advance, "paid": frappe.utils.flt(se.payable) - left}\n    elif d.kind == "Cash" and d.advance and d.status == "Approved":\n        ad = frappe.db.get_value("Employee Advance", d.advance, ["status", "paid_amount", "docstatus"], as_dict=True)\n        if ad and ad.docstatus == 1:\n            booked = {"advance": d.advance, "status": ad.status or "", "paid": ad.paid_amount}\n    return {"name": d.name, "hq": hq, "team": team, "resent": resent, "booked": booked, "batch": d.get("batch") or "", "employee": d.employee, "employee_name": d.employee_name, "user": d.user,\n            "kind": d.kind, "status": d.status, "amount": d.amount, "claim": d.claim or "", "advance": d.advance or "",\n            "purpose": d.purpose or "", "step": d.step, "next_approver": d.next_approver or "", "next_label": d.next_label or "",\n            "note": d.note or "", "decided_by": d.decided_by or "", "decided_on": str(d.decided_on or ""),\n            "creation": str(d.creation), "modified": str(d.modified), "steps": steps, "bills": bills}\n\n\ndef held_up(d, i, now):\n    # why step i of a waiting request should not wait on its approver, else ""\n    st = d.steps[i]\n    m = frappe.db.get_value("Employee", {"user_id": st.user, "status": "Active"}, "name")\n    if not m or not frappe.db.get_value("User", st.user, "enabled"):\n        return "No longer active -- skipped"\n    day = str(now)[:10]\n    if frappe.db.exists("Leave Application", {"employee": m, "status": "Approved", "docstatus": 1,\n                                              "from_date": ["<=", day], "to_date": [">=", day]}):\n        return "On leave -- skipped"\n    for b in d.bills or []:\n        if frappe.utils.flt(b.ai_score) < 70:\n            return ""        # a High-risk bill never skips a level: it waits\n    arrived = frappe.utils.get_datetime(d.creation)\n    if i > 0 and d.steps[i - 1].decided_on:\n        prev = frappe.utils.get_datetime(d.steps[i - 1].decided_on)\n        if prev > arrived:\n            arrived = prev\n    due = arrived\n    n = 0\n    while n < 2:\n        due = frappe.utils.add_days(due, 1)\n        if due.weekday() != 6:\n            n = n + 1\n    if frappe.utils.get_datetime(now) >= due:\n        return "No action in 2 working days -- moved up"\n    return ""\n\n\ndef sweep(d, now, tell):\n    # moves a waiting request past the steps nobody can act on -> True when it\n    # moved (the caller saves). Stops at SM / ZSM: never on to a GM or the CEO.\n    moved = False\n    guard = 0\n    while d.status == "Waiting" and guard < 10:\n        guard = guard + 1\n        i = frappe.utils.cint(d.step)\n        if i >= len(d.steps) - 1:\n            break\n        if str(d.steps[i].level or "").upper() in ["SM", "ZSM"] or str(d.steps[i + 1].level or "").upper() in ["GM", "CEO"]:\n            break\n        why = held_up(d, i, now)\n        if not why:\n            break\n        st = d.steps[i]\n        st.decision = "Skipped"\n        st.decided_on = now\n        st.note = why\n        d.step = i + 1\n        d.next_approver = d.steps[i + 1].user\n        d.next_label = d.steps[i + 1].level\n        moved = True\n        if why[:9] == "No action":\n            notify(st.user, "Moved up to " + str(d.steps[i + 1].approver_name or d.next_approver) + " (no action in 2 working days): "\n                   + str(d.employee_name) + " · " + frappe.utils.fmt_money(d.amount, currency="INR"), d.name)\n    if moved and tell:\n        notify(d.next_approver, ("Settlement" if d.kind == "Bills" else "Cash request") + " to approve: " + str(d.employee_name)\n               + " · " + frappe.utils.fmt_money(d.amount, currency="INR"), d.name)\n    return moved\n\n\ndef last_rejected(row, employee):\n    # the latest request this bill row was in, when it was rejected -> {parent, amount, bill}\n    hits = frappe.db.sql("select parent, amount, bill from `tabSettlement Bill` where `row` = %s and parenttype = \'Settlement Request\' order by creation desc limit 5",\n                         (row,), as_dict=True)\n    for h in hits or []:\n        st = frappe.db.get_value("Settlement Request", h.parent, ["status", "employee"], as_dict=True)\n        if not st or st.status == "Withdrawn":\n            continue\n        if st.status == "Rejected" and st.employee == employee:\n            return h\n        return None\n    return None\n\n\ndef carry(d, old_name):\n    # the steps approved on the rejected request stay approved, up to whoever rejected it\n    old = frappe.get_doc("Settlement Request", old_name)\n    done = {}\n    for st in old.steps or []:\n        if st.decision == "Approved":\n            done[st.user] = st\n    i = 0\n    while i < len(d.steps) - 1 and done.get(d.steps[i].user):\n        o = done.get(d.steps[i].user)\n        d.steps[i].decision = "Approved"\n        d.steps[i].decided_on = o.decided_on\n        d.steps[i].note = "Approved before (" + old_name + ")"\n        i = i + 1\n    if i:\n        d.step = i\n        d.next_approver = d.steps[i].user\n        d.next_label = d.steps[i].level\n\n\ndef account_for(title, cfg):\n    # the expense account for a bill, from its title\n    t = " " + str(title or "").lower() + " "\n    for k in cfg["kinds"]:\n        for w in k["words"]:\n            if (" " + w) in t:\n                return k["account"]\n    return cfg["other"]\n\n\ndef outstanding(je, employee):\n    # what of a bill\'s Journal Entry is still owed to the employee on 2120\n    # (Payment Ledger: the entry\'s own credit, less the payments against it)\n    r = frappe.db.sql("""select sum(amount_in_account_currency) from `tabPayment Ledger Entry`\n        where against_voucher_type = \'Journal Entry\' and against_voucher_no = %s and party_type = \'Employee\'\n          and party = %s and account = %s and delinked = 0""", (je, employee, BOOKING["payable"]))\n    s = frappe.utils.flt(r[0][0] if r and r[0] else 0)\n    return -s if s < 0 else s\n\n\ndef book_bill(d, b, cfg):\n    # one CEO-approved bill -> ONE submitted Journal Entry -> its name\n    se = frappe.db.get_value("Settlement Expense", b.row, ["name", "bill_date", "title", "amount", "bill"], as_dict=True)\n    if not se:\n        frappe.throw("Bill " + str(b.row) + " is gone -- it cannot be booked.")\n    amt = frappe.utils.flt(se.amount)\n    acct = account_for(se.title or b.title, cfg)\n    remark = ("Settlement " + d.name + " · " + se.name + ": " + str(se.title or "") + " (bill of " + str(se.bill_date)\n              + "), approved up to the CEO in the app.")\n    rows = [{"account": acct, "debit_in_account_currency": amt, "cost_center": cfg["cost_center"], "user_remark": str(se.title or "")[:140]}]\n    # the employee\'s unspent cash advances (paid, not yet used) cover it first\n    left = amt\n    used = 0\n    for a in frappe.get_all("Employee Advance", filters={"employee": d.employee, "docstatus": 1, "advance_account": cfg["advance"], "paid_amount": [">", 0]},\n                            fields=["name", "paid_amount", "claimed_amount", "return_amount"], order_by="posting_date asc", limit_page_length=50):\n        un = frappe.utils.flt(a.paid_amount) - frappe.utils.flt(a.claimed_amount) - frappe.utils.flt(a.return_amount)\n        if un <= 0 or left <= 0:\n            continue\n        take = un if un < left else left\n        rows.append({"account": cfg["advance"], "party_type": "Employee", "party": d.employee, "credit_in_account_currency": take,\n                     "reference_type": "Employee Advance", "reference_name": a.name, "cost_center": cfg["cost_center"]})\n        left = left - take\n        used = used + take\n    if left > 0:\n        rows.append({"account": cfg["payable"], "party_type": "Employee", "party": d.employee, "credit_in_account_currency": left,\n                     "cost_center": cfg["cost_center"]})\n    je = frappe.get_doc({"doctype": "Journal Entry", "voucher_type": "Journal Entry", "company": cfg["company"],\n                         "posting_date": frappe.utils.today(), "user_remark": remark, "accounts": rows})\n    je.flags.ignore_permissions = True\n    je.insert(ignore_permissions=True)\n    je.submit()\n    # the bill photo on the entry too, for Accounts\n    if se.bill:\n        try:\n            frappe.get_doc({"doctype": "File", "file_url": se.bill, "attached_to_doctype": "Journal Entry",\n                            "attached_to_name": je.name, "is_private": 1}).insert(ignore_permissions=True)\n        except Exception:\n            pass        # the bill stays on the Settlement Expense\n    # all of it out of the cash already given: nothing left to pay -> Paid\n    vals = {"journal_entry": je.name, "expense_account": acct, "from_advance": used, "payable": left}\n    if left <= 0:\n        vals["status"] = "Paid"\n    frappe.db.set_value("Settlement Expense", se.name, vals)\n    return je.name\n\n\ndef book_cash(d, cfg):\n    # a CEO-approved cash request -> its Employee Advance submitted (to be paid)\n    ea = frappe.get_doc("Employee Advance", d.advance)\n    if ea.docstatus == 1:\n        return ea.name\n    ea.advance_account = cfg["advance"]\n    if frappe.get_meta("Employee Advance").has_field("repay_unclaimed_amount_from_salary"):\n        ea.repay_unclaimed_amount_from_salary = 0      # NOT from salary (user 2026-11-18): the employee pays unspent cash back to the bank; Accounts record it with the advance\'s Return\n    ea.flags.ignore_permissions = True\n    ea.flags.settlement = True\n    ea.submit()\n    return ea.name\n\n\ndef finalize(d, by, cfg, book):\n    # the LAST step approved (the CEO, on a batch): the bill\n    # is Verified and booked in the accounts (or the cash advance submitted),\n    # to be paid in a payment batch the CEO approves\n    d.status = "Approved"\n    d.next_approver = None\n    d.next_label = None\n    d.decided_by = by\n    d.decided_on = frappe.utils.now()\n    if d.kind == "Bills":\n        for b in d.bills or []:\n            frappe.db.set_value("Settlement Expense", b.row, "status", "Verified")\n    if book and booking_ready(cfg):\n        try:\n            if d.kind == "Bills":\n                for b in d.bills or []:\n                    book_bill(d, b, cfg)\n            elif d.advance:\n                book_cash(d, cfg)\n        except Exception as err:\n            frappe.throw("Not approved: it could not be booked in the accounts (" + str(err)[:300] + "). Nothing was changed -- tell IT.")\n    notify(d.user, ("Your bill is approved -- it will be paid in the next payment run" if d.kind == "Bills" else "Your cash request is approved -- it will be paid in the next payment run")\n           + " (" + frappe.utils.fmt_money(d.amount, currency="INR") + ")", d.name)\n\n\ndef make_batch(reqs, by, ceo_user):\n    # the requests that just reached the CEO -> ONE Settlement Batch for him\n    if not reqs:\n        return None\n    who = frappe.db.get_value("Employee", {"user_id": by, "status": "Active"}, "employee_name") or by\n    items = []\n    total = 0\n    for d in reqs:\n        items.append({"request": d.name, "employee": d.employee, "employee_name": d.employee_name,\n                      "amount": d.amount, "title": str(d.purpose or "")[:140]})\n        total = total + frappe.utils.flt(d.amount)\n    sb = frappe.get_doc({"doctype": "Settlement Batch", "status": "Waiting", "made_by": by, "made_by_name": who,\n                         "amount": total, "count": len(items), "lines": items})\n    sb.insert(ignore_permissions=True)\n    for d in reqs:\n        d.batch = sb.name\n    notify(ceo_user, "Batch to approve from " + str(who) + ": " + str(len(items)) + (" bill" if len(items) == 1 else " bills")\n           + " · " + frappe.utils.fmt_money(total, currency="INR"), sb.name)\n    return sb.name\n\n\ndef close_batch(name, by):\n    # a batch with nothing left waiting is Done\n    if not name:\n        return\n    left = frappe.get_all("Settlement Request", filters={"batch": name, "status": "Waiting"}, pluck="name", limit_page_length=1)\n    if not left and frappe.db.get_value("Settlement Batch", name, "status") == "Waiting":\n        frappe.db.set_value("Settlement Batch", name, {"status": "Done", "decided_by": by, "decided_on": frappe.utils.now()})\n\n\ndef approve_one(d, me, cfg, book):\n    # the caller\'s step approved -> "ceo" when the request now waits on the CEO\n    # (it needs a batch), "done" when it was the last step, else ""\n    i = frappe.utils.cint(d.step)\n    step = d.steps[i]\n    step.decided_on = frappe.utils.now()\n    step.decision = "Approved"\n    if i + 1 < len(d.steps):\n        d.step = i + 1\n        d.next_approver = d.steps[i + 1].user\n        d.next_label = d.steps[i + 1].level\n        # the next approver on leave or gone: straight past them (17 Nov 2026)\n        sweep(d, frappe.utils.now(), False)\n        if d.next_label == "CEO":\n            return "ceo"\n        notify(d.next_approver, ("Settlement" if d.kind == "Bills" else "Cash request") + " to approve: " + str(d.employee_name)\n               + " · " + frappe.utils.fmt_money(d.amount, currency="INR"), d.name)\n        return ""\n    finalize(d, me, cfg, book)\n    return "done"\n\n\ndef reject_one(d, me, who, note):\n    i = frappe.utils.cint(d.step)\n    step = d.steps[i]\n    step.decided_on = frappe.utils.now()\n    step.note = note\n    step.decision = "Rejected"\n    d.status = "Rejected"\n    d.note = note\n    d.next_approver = None\n    d.next_label = None\n    d.decided_by = me\n    d.decided_on = frappe.utils.now()\n    for b in d.bills or []:\n        frappe.db.set_value("Settlement Expense", b.row, {"status": "Checked", "settlement": None,\n                                                         "review_note": ("Returned by " + who + ": " + note)[:500]})\n    if d.advance and frappe.db.get_value("Employee Advance", d.advance, "docstatus") == 0:\n        frappe.delete_doc("Employee Advance", d.advance, ignore_permissions=True, force=True)\n        d.advance = None\n    notify(d.user, "Sent back by " + who + ": " + note, d.name)\n\n\ndef booking_ready(cfg):\n    return frappe.db.exists("Account", cfg["payable"]) and frappe.db.exists("Account", cfg["advance"])\n\n\ndef notify(user, subject, name):\n    try:\n        frappe.get_doc({"doctype": "Notification Log", "for_user": user, "type": "Alert", "subject": subject,\n                        "document_type": "Settlement Request", "document_name": name}).insert(ignore_permissions=True)\n    except Exception:\n        pass\n\n\nBILL_FIELDS = ["name", "employee", "bill_date", "title", "amount", "bill", "proof", "hand_note", "status", "settlement", "review_note",\n               "journal_entry", "from_advance", "payable", "creation", "modified"]\n\n\ndef bill_out(b):\n    # a Settlement Expense as the app reads it (the rep never sees the score)\n    paid = 0\n    if b.journal_entry:\n        paid = frappe.utils.flt(b.payable) - outstanding(b.journal_entry, b.employee)\n    return {"name": b.name, "date": str(b.bill_date or ""), "title": b.title or "", "amount": frappe.utils.flt(b.amount),\n            "bill": b.bill or "", "proof": b.proof or "", "hand_note": b.hand_note or "", "status": b.status or "Checking",\n            "settlement": b.settlement or "", "review": b.review_note or "", "entry": b.journal_entry or "",\n            "from_advance": frappe.utils.flt(b.from_advance), "payable": frappe.utils.flt(b.payable), "paid": paid,\n            "creation": str(b.creation), "modified": str(b.modified)}\n\n\ndef own_file(url, user):\n    # a private File the caller uploaded, not yet attached to anything -> its name\n    if not url:\n        return None\n    # the same photo uploaded twice shares its file_url: take the copy attached to nothing\n    f = frappe.db.get_value("File", {"file_url": url, "owner": user, "attached_to_name": ["is", "not set"]}, "name", order_by="creation desc")\n    if not f:\n        if frappe.db.exists("File", {"file_url": url, "owner": user}):\n            frappe.throw("That photo is already on another bill -- add it again.")\n        frappe.throw("That photo was not uploaded by you -- add it again.")\n    return f\n\n\nfd = frappe.form_dict\naction = str(fd.get("action") or "mine")\nme = frappe.session.user\nif not me or me == "Guest":\n    frappe.throw("Please log in", frappe.PermissionError)\nemp = frappe.db.get_value("Employee", {"user_id": me, "status": "Active"}, ["name", "employee_name", "department"], as_dict=True)\noverview = me == "Administrator" or bool(emp and emp.department in OVERVIEW_DEPARTMENTS)\nif not overview and frappe.db.exists("Has Role", {"parent": me, "parenttype": "User", "role": ["in", OVERVIEW_ROLES]}):\n    overview = True\n\n\ndef new_request(emp, me, kind, amount, purpose, claim, advance, bills, chain):\n    users = []\n    steps = []\n    for c in chain:\n        users.append(c["user"])\n        steps.append({"user": c["user"], "approver_name": c["name"], "level": c["level"]})\n    d = frappe.get_doc({\n        "doctype": "Settlement Request",\n        "employee": emp.name,\n        "employee_name": emp.employee_name,\n        "user": me,\n        "kind": kind,\n        "status": "Waiting",\n        "amount": amount,\n        "purpose": purpose,\n        "claim": claim,\n        "advance": advance,\n        "step": 0,\n        "next_approver": chain[0]["user"],\n        "next_label": chain[0]["level"],\n        "approvers": "|" + "|".join(users) + "|",\n        "steps": steps,\n        "bills": bills,\n    })\n    d.insert(ignore_permissions=True)\n    return d\n\n\nif action == "mine":\n    rows = []\n    preview = []\n    if emp:\n        for r in frappe.get_all("Settlement Request", filters={"employee": emp.name, "status": ["!=", "Withdrawn"]},\n                                pluck="name", order_by="creation desc", limit_page_length=30):\n            rows.append(shape(frappe.get_doc("Settlement Request", r)))\n        preview = chain_of(emp.name, CEO_USER, CEO_DESIGNATION, LEVELS)\n    frappe.response["message"] = {"requests": rows, "chain": preview, "overview": overview}\n\nelif action == "bills":\n    out = []\n    if emp:\n        flt = {"employee": emp.name}\n        names = []\n        for x in str(fd.get("names") or "").split(","):\n            if x.strip():\n                names.append(x.strip())\n        if names:\n            flt["name"] = ["in", names]\n        for b in frappe.get_all("Settlement Expense", filters=flt, fields=BILL_FIELDS, order_by="bill_date desc, creation desc", limit_page_length=500):\n            out.append(bill_out(b))\n    frappe.response["message"] = {"bills": out, "employee": emp.name if emp else None}\n\nelif action == "add_bill":\n    if not emp:\n        frappe.throw("No active employee is linked to this login.")\n    day = str(fd.get("bill_date") or "")[:10]\n    title = " ".join(str(fd.get("title") or "").split())[:140]\n    amount = frappe.utils.flt(fd.get("amount"))\n    bill = str(fd.get("bill") or "").strip()\n    proof = str(fd.get("proof") or "").strip()\n    if not (len(day) == 10 and day[4] == "-" and day[7] == "-"):\n        frappe.throw("Which date is the bill of?")\n    if day > frappe.utils.today():\n        frappe.throw("The bill\'s date cannot be in the future.")\n    if not title:\n        frappe.throw("Say what the bill was for.")\n    if amount <= 0:\n        frappe.throw("Enter the bill amount.")\n    if not bill:\n        frappe.throw("Add a photo of the bill.")\n    files = [[own_file(bill, me), "bill"]]\n    if proof:\n        files.append([own_file(proof, me), "proof"])\n    se = frappe.get_doc({"doctype": "Settlement Expense", "employee": emp.name, "employee_name": emp.employee_name, "user": me,\n                         "status": "Checking", "bill_date": day, "title": title, "amount": amount, "bill": bill, "proof": proof or None,\n                         "hand_note": " ".join(str(fd.get("hand_note") or "").split())[:500] or None})\n    se.insert(ignore_permissions=True)\n    for f in files:\n        frappe.db.set_value("File", f[0], {"attached_to_doctype": "Settlement Expense", "attached_to_name": se.name, "attached_to_field": f[1]})\n    b = frappe.db.get_value("Settlement Expense", se.name, BILL_FIELDS, as_dict=True)\n    frappe.response["message"] = {"bill": bill_out(b)}\n\nelif action == "remove_bill":\n    name = str(fd.get("name") or "")\n    b = frappe.db.get_value("Settlement Expense", name, ["name", "employee", "status", "settlement"], as_dict=True) if name else None\n    if not b or not emp or b.employee != emp.name:\n        frappe.throw("That is not your bill.", frappe.PermissionError)\n    if b.status not in ["Checking", "Checked"] or b.settlement:\n        frappe.throw("A bill sent for approval can only be taken back from the approval itself.")\n    for f in frappe.get_all("File", filters={"attached_to_doctype": "Settlement Expense", "attached_to_name": name}, pluck="name"):\n        frappe.delete_doc("File", f, ignore_permissions=True, force=True)\n    # its place in the duplicate register is freed, so the same bill can be added again\n    if frappe.db.exists("DocType", "Bill Fingerprint"):\n        for p in frappe.get_all("Bill Fingerprint", filters={"trip": name, "status": "Used"}, pluck="name"):\n            frappe.delete_doc("Bill Fingerprint", p, ignore_permissions=True, force=True)\n    frappe.delete_doc("Settlement Expense", name, ignore_permissions=True, force=True)\n    frappe.response["message"] = {"removed": name}\n\nelif action == "score":\n    # the app\'s bill check (its checker login) writes what it read and the score\n    if me not in SCORERS:\n        frappe.throw("Only the bill check scores bills.", frappe.PermissionError)\n    name = str(fd.get("name") or "")\n    b = frappe.db.get_value("Settlement Expense", name, ["name", "status", "amount", "bill"], as_dict=True) if name else None\n    if not b:\n        frappe.throw("No such bill: " + name)\n    # changed or decided while the check ran: leave it\n    if b.status != "Checking" or abs(frappe.utils.flt(b.amount) - frappe.utils.flt(fd.get("amount"))) > 0.5 or str(b.bill or "") != str(fd.get("bill") or ""):\n        frappe.response["message"] = {"skipped": 1, "status": b.status}\n    else:\n        sc = frappe.utils.flt(fd.get("score"))\n        risk = "Low" if sc >= 90 else ("Medium" if sc >= 70 else "High")\n        vals = {"ai_score": sc, "ai_risk": risk, "ai_reason": str(fd.get("reason") or "")[:500], "status": "Checked",\n                "read_vendor": str(fd.get("read_vendor") or "")[:140] or None, "bill_meta": str(fd.get("meta") or "")[:20000] or None}\n        if fd.get("read_amount"):\n            vals["read_amount"] = frappe.utils.flt(fd.get("read_amount"))\n        rd = str(fd.get("read_date") or "")[:10]\n        if len(rd) == 10 and rd[4] == "-":\n            vals["read_date"] = rd\n        frappe.db.set_value("Settlement Expense", name, vals)\n        frappe.response["message"] = {"name": name, "score": sc, "risk": risk, "status": "Checked"}\n\nelif action == "send_bills":\n    if not emp:\n        frappe.throw("No active employee is linked to this login.")\n    # rows=a,b: only those bills (the app sends a bill the moment it is added,\n    # 16 Nov 2026 -- so a sent-back bill is not resent before it is fixed)\n    only = []\n    for x in str(fd.get("rows") or "").split(","):\n        if x.strip():\n            only.append(x.strip())\n    rflt = [["employee", "=", emp.name], ["status", "=", "Checked"], ["settlement", "is", "not set"]]\n    if only:\n        rflt.append(["name", "in", only])\n    picked = frappe.get_all("Settlement Expense", filters=rflt,\n                            fields=["name", "bill_date", "title", "amount", "bill", "ai_score", "ai_risk", "ai_reason"],\n                            order_by="bill_date asc, creation asc", limit_page_length=500)\n    claim = None\n    if not picked:\n        frappe.throw("No checked bills to send -- add a bill, and wait for its check to finish.")\n    chain = chain_of(emp.name, CEO_USER, CEO_DESIGNATION, LEVELS)\n    # 16 Nov 2026 (the user): EACH BILL IS ITS OWN REQUEST, with its own\n    # chain, so every row of the claim carries its own status (and its own\n    # Settlement Request link) and one bill never holds up another.\n    total = 0\n    made = []\n    now = frappe.utils.now()\n    for r in picked:\n        total = total + frappe.utils.flt(r.amount)\n        title = str(r.title or "")[:140]\n        bill = {"row": r.name, "bill_date": r.bill_date, "title": title, "amount": r.amount,\n                "bill": r.bill, "ai_score": r.ai_score, "ai_risk": r.ai_risk, "ai_reason": r.ai_reason}\n        # sent again (17 Nov 2026): back to whoever rejected it, unless the\n        # photo changed or the amount went up (looked up BEFORE the new request\n        # exists -- it would be the latest one with this bill)\n        prev = last_rejected(r.name, emp.name)\n        d = new_request(emp, me, "Bills", r.amount, title or "1 bill", claim, None, [bill], chain)\n        changed = False\n        if prev:\n            d.resent_from = prev.parent\n            if str(prev.bill or "") == str(r.bill or "") and frappe.utils.flt(r.amount) <= frappe.utils.flt(prev.amount) + 0.5:\n                carry(d, prev.parent)\n            changed = True\n        moved = sweep(d, now, False)\n        # straight to the CEO (a GM\'s own bill; sent again to the CEO who\n        # rejected it): a batch of its own\n        if d.next_label == "CEO" and not d.get("batch"):\n            make_batch([d], me, CEO_USER)\n            moved = True\n        if moved or changed:\n            d.save(ignore_permissions=True)\n        frappe.db.set_value("Settlement Expense", r.name, {"status": "In Approval", "settlement": d.name, "review_note": None})\n        made.append(d)\n        # the approvers may open the bill and its photos (read only)\n        for c in chain:\n            if c["user"] != me and not frappe.db.exists("DocShare", {"share_doctype": "Settlement Expense", "share_name": r.name, "user": c["user"]}):\n                sh = frappe.get_doc({"doctype": "DocShare", "share_doctype": "Settlement Expense", "share_name": r.name, "user": c["user"],\n                                     "read": 1, "write": 0, "share": 0, "notify_by_email": 0})\n                sh.flags.ignore_share_permission = True\n                sh.insert(ignore_permissions=True)\n    # one alert per approver for the whole send, not one per bill (a bill\n    # sent again may wait on someone further up)\n    n = len(made)\n    tell = {}\n    for d in made:\n        t = tell.get(d.next_approver) or {"n": 0, "amount": 0, "name": d.name}\n        t["n"] = t["n"] + 1\n        t["amount"] = t["amount"] + frappe.utils.flt(d.amount)\n        tell[d.next_approver] = t\n    for u in tell:\n        t = tell[u]\n        notify(u, str(t["n"]) + (" bill" if t["n"] == 1 else " bills") + " to approve: " + str(emp.employee_name) + " · " + frappe.utils.fmt_money(t["amount"], currency="INR"), t["name"])\n    out = []\n    for d in made:\n        out.append(shape(d))\n    frappe.response["message"] = {"requests": out, "count": n, "amount": total}\n\nelif action == "send_cash":\n    if not emp:\n        frappe.throw("No active employee is linked to this login.")\n    amount = frappe.utils.flt(fd.get("amount"))\n    purpose = " ".join(str(fd.get("purpose") or "").split())[:500]\n    if amount <= 0:\n        frappe.throw("Say how much you need.")\n    if not purpose:\n        frappe.throw("Say what the cash is for.")\n    chain = chain_of(emp.name, CEO_USER, CEO_DESIGNATION, LEVELS)\n    ea = frappe.get_doc({"doctype": "Employee Advance", "employee": emp.name, "posting_date": frappe.utils.today(), "purpose": purpose,\n                         "advance_amount": amount, "currency": "INR", "exchange_rate": 1})\n    ea.flags.settlement = True       # "Employee Advance Task" makes no Accounts Task for it\n    ea.insert(ignore_permissions=True)\n    d = new_request(emp, me, "Cash", amount, purpose, None, ea.name, [], chain)\n    if d.next_label == "CEO":\n        make_batch([d], me, CEO_USER)\n        d.save(ignore_permissions=True)\n    notify(chain[0]["user"], "Cash request to approve: " + str(emp.employee_name) + " · " + frappe.utils.fmt_money(amount, currency="INR"), d.name)\n    frappe.response["message"] = {"request": shape(d)}\n\nelif action == "withdraw":\n    name = str(fd.get("name") or "")\n    d = frappe.get_doc("Settlement Request", name) if name and frappe.db.exists("Settlement Request", name) else None\n    if not d or not emp or d.employee != emp.name:\n        frappe.throw("That is not your request.", frappe.PermissionError)\n    if d.status != "Waiting" or frappe.utils.cint(d.step) > 0:\n        frappe.throw("It can only be taken back before anyone has approved it.")\n    for b in d.bills or []:\n        frappe.db.set_value("Settlement Expense", b.row, {"status": "Checked", "settlement": None})\n    if d.advance and frappe.db.get_value("Employee Advance", d.advance, "docstatus") == 0:\n        frappe.delete_doc("Employee Advance", d.advance, ignore_permissions=True, force=True)\n        d.advance = None\n    d.status = "Withdrawn"\n    d.next_approver = None\n    d.next_label = None\n    d.save(ignore_permissions=True)\n    frappe.response["message"] = {"request": shape(d)}\n\nelif action == "queue":\n    waiting = []\n    team = []\n    decided = []\n    since = frappe.utils.add_days(frappe.utils.today(), -60)\n    for r in frappe.get_all("Settlement Request", filters={"status": "Waiting", "next_approver": me}, pluck="name", order_by="creation asc", limit_page_length=200):\n        waiting.append(shape(frappe.get_doc("Settlement Request", r)))\n    flt = {"approvers": ["like", "%|" + me + "|%"], "modified": [">=", since]}\n    if overview:\n        flt = {"modified": [">=", since]}\n    for r in frappe.get_all("Settlement Request", filters=flt, pluck="name", order_by="modified desc", limit_page_length=300):\n        d = frappe.get_doc("Settlement Request", r)\n        if d.status == "Withdrawn" or (d.status == "Waiting" and d.next_approver == me):\n            continue\n        mine_done = False\n        for s in d.steps or []:\n            if s.user == me and s.decision:\n                mine_done = True\n        if mine_done:\n            decided.append(shape(d))\n        elif d.status == "Waiting":\n            team.append(shape(d))\n        elif overview:\n            decided.append(shape(d))\n    frappe.response["message"] = {"waiting": waiting, "team": team, "decided": decided, "overview": overview, "me": me}\n\nelif action == "decide":\n    name = str(fd.get("name") or "")\n    decision = str(fd.get("decision") or "")\n    note = " ".join(str(fd.get("note") or "").split())[:1000]\n    d = frappe.get_doc("Settlement Request", name) if name and frappe.db.exists("Settlement Request", name) else None\n    if not d:\n        frappe.throw("No such request.")\n    if d.status != "Waiting":\n        frappe.throw("This request is already " + str(d.status).lower() + ".")\n    if d.next_approver != me:\n        frappe.throw("This request is waiting on someone else.", frappe.PermissionError)\n    who = str((emp and emp.employee_name) or me)\n    batch = d.get("batch")\n    if decision == "Approve":\n        d.steps[frappe.utils.cint(d.step)].note = note\n        if approve_one(d, me, BOOKING, BOOK) == "ceo":\n            make_batch([d], me, CEO_USER)          # one bill sent on its own: a batch of one\n    elif decision == "Reject":\n        if not note:\n            frappe.throw("Say why it is rejected -- the requester sees it.")\n        reject_one(d, me, who, note)\n    else:\n        frappe.throw("Approve or Reject?")\n    d.save(ignore_permissions=True)\n    close_batch(batch, me)\n    frappe.response["message"] = {"request": shape(d)}\n\nelif action == "approve_many":\n    # 18 Nov 2026: the approver\'s selection in one go -- what reaches the CEO\n    # goes to him as ONE batch\n    names = []\n    for x in str(fd.get("names") or "").split(","):\n        if x.strip() and x.strip() not in names:\n            names.append(x.strip())\n    to_ceo = []\n    done = 0\n    skipped = []\n    batches = []\n    for name in names:\n        d = frappe.get_doc("Settlement Request", name) if frappe.db.exists("Settlement Request", name) else None\n        if not d or d.status != "Waiting" or d.next_approver != me:\n            skipped.append(name)\n            continue\n        if d.get("batch") and d.get("batch") not in batches:\n            batches.append(d.get("batch"))\n        r = approve_one(d, me, BOOKING, BOOK)\n        if r == "ceo":\n            to_ceo.append(d)\n        else:\n            d.save(ignore_permissions=True)\n        done = done + 1\n    sb = make_batch(to_ceo, me, CEO_USER)\n    for d in to_ceo:\n        d.save(ignore_permissions=True)\n    for b in batches:\n        close_batch(b, me)\n    frappe.response["message"] = {"approved": done, "batch": sb, "to_ceo": len(to_ceo), "skipped": skipped}\n\nelif action == "ceo_batches":\n    if me != CEO_USER and not overview:\n        frappe.throw("Batches are for the CEO.", frappe.PermissionError)\n    since = frappe.utils.add_days(frappe.utils.today(), -30)\n    out = []\n    names = frappe.get_all("Settlement Batch", filters={"status": "Waiting"}, pluck="name", order_by="creation asc", limit_page_length=200)\n    for x in frappe.get_all("Settlement Batch", filters={"status": "Done", "modified": [">=", since]}, pluck="name", order_by="modified desc", limit_page_length=100):\n        names.append(x)\n    for n in names:\n        sb = frappe.get_doc("Settlement Batch", n)\n        reqs = []\n        for it in sb.lines or []:\n            if frappe.db.exists("Settlement Request", it.request):\n                reqs.append(shape(frappe.get_doc("Settlement Request", it.request)))\n        out.append({"name": sb.name, "status": sb.status, "made_by": sb.made_by, "made_by_name": sb.made_by_name, "amount": sb.amount,\n                    "count": sb.count, "creation": str(sb.creation), "decided_on": str(sb.decided_on or ""), "requests": reqs})\n    frappe.response["message"] = {"batches": out, "ceo": me == CEO_USER}\n\nelif action == "decide_batch":\n    # the CEO approves what is still waiting on him in the batch (bills he\n    # sent back one by one are already back with the rep): booked, final\n    if me != CEO_USER:\n        frappe.throw("Only the CEO approves a batch.", frappe.PermissionError)\n    name = str(fd.get("name") or "")\n    if not frappe.db.exists("Settlement Batch", name):\n        frappe.throw("No such batch.")\n    if frappe.db.get_value("Settlement Batch", name, "status") != "Waiting":\n        frappe.throw("This batch is already decided.")\n    n = 0\n    total = 0\n    # oldest first, so the cash advance covers the earliest bills (23 Nov 2026)\n    for r in frappe.get_all("Settlement Request", filters={"batch": name, "status": "Waiting", "next_approver": me}, pluck="name", order_by="creation asc", limit_page_length=500):\n        d = frappe.get_doc("Settlement Request", r)\n        approve_one(d, me, BOOKING, BOOK)\n        d.save(ignore_permissions=True)\n        n = n + 1\n        total = total + frappe.utils.flt(d.amount)\n    close_batch(name, me)\n    frappe.response["message"] = {"approved": n, "amount": total, "batch": name}\n\nelse:\n    frappe.throw("Unknown action.")\n'
ACC_SRC = '# Server Script "Settlement Accounts API" -- type API, method settlement_accounts\n# (18 Nov 2026). Accounts pay employees for settlement bills IN ONE PLACE in\n# the ERP: the "Settlement Payments" dashboard (Web Page /settlement-payments,\n# listed on the Dashboards workspace next to Field Expenses) -- management:\n# paying is Accounts\' work in the ERP, not in the app, and it must be clear\n# and in one place.\n#\n# What is owed: bills the CEO approved -- each a Settlement Expense booked as\n# ONE Journal Entry (23 Nov 2026; was an Expense Claim) whose credit on 2120\n# Employee Expense Payable (party = the Employee) is not paid yet -- and\n# approved cash requests -- submitted Employee Advances on "Employee Expense\n# Advances", Unpaid. Both are booked by the Settlement API. Nothing here reads\n# Expense Claim any more (that holds only the field TA/DA).\n#\n#   GET  action=due                         one row per employee: bills, advances, total, bank details;\n#                                           the bank accounts; payments of the last 30 days\n#   POST action=pay   employees=a,b, bank_account, date, utr [, utr_<EMPLOYEE>]\n#                                           after paying at the bank: per employee ONE Bank Entry\n#                                           (Journal Entry) for the bills -- Dr 2120 against each bill\'s\n#                                           Journal Entry, Cr the bank (ERPNext will not take a Payment\n#                                           Entry against a Journal Entry owed to an employee; tested on\n#                                           UAT 23 Nov 2026) -- and one Payment Entry for the advances;\n#                                           the bills / advances turn Paid; the employee is told\n#\n# Only Accounts (Accounts User / Accounts Manager / System Manager, or a user\n# of the "Accounts" project). Amounts are always worked out here, never taken\n# from the screen. safe_exec: no import, no .format(), no tuple unpacking, no\n# underscore names; comprehensions and defs never read top-level names.\n\nACCOUNTS_ROLES = ["System Manager", "Accounts Manager", "Accounts User"]\nACCOUNTS_PROJECT = "PROJ-2026-2027-0012"       # "Accounts"\nPAY = {\n    "company": "Elbrit Lifesciences Private Limited",\n    "payable": "2120 - Employee Expense Payable - ELPL",\n    "advance": "Employee Expense Advances - ELPL",\n    "bank": "234851000001 - ICICI BANK OD/CC Account - ELPL",     # the default; Accounts may pick another\n}\n\n\ndef left_on(je, employee, payable):\n    # what of a bill\'s Journal Entry is still owed to the employee (Payment Ledger)\n    r = frappe.db.sql("""select sum(amount_in_account_currency) from `tabPayment Ledger Entry`\n        where against_voucher_type = \'Journal Entry\' and against_voucher_no = %s and party_type = \'Employee\'\n          and party = %s and account = %s and delinked = 0""", (je, employee, payable))\n    s = frappe.utils.flt(r[0][0] if r and r[0] else 0)\n    return -s if s < 0 else s\n\n\ndef owed(employee_list, cfg):\n    # {employee: {employee, employee_name, claims: [...], advances: [...], total}}\n    # "claims" are the bills (Settlement Expense), each against its Journal Entry\n    flt = frappe.utils.flt\n    out = {}\n    sf = {"status": "Verified", "journal_entry": ["is", "set"], "payable": [">", 0]}\n    af = {"docstatus": 1, "advance_account": cfg["advance"], "status": "Unpaid"}\n    if employee_list:\n        sf["employee"] = ["in", employee_list]\n        af["employee"] = ["in", employee_list]\n    for c in frappe.get_all("Settlement Expense", filters=sf, fields=["name", "employee", "employee_name", "bill_date", "title", "bill",\n                                                                   "expense_account", "journal_entry", "modified"],\n                            order_by="bill_date asc", limit_page_length=0):\n        due = left_on(c.journal_entry, c.employee, cfg["payable"])\n        if due <= 0.005:\n            continue\n        e = out.get(c.employee) or {"employee": c.employee, "employee_name": c.employee_name, "claims": [], "advances": [], "total": 0}\n        e["claims"].append({"name": c.name, "entry": c.journal_entry, "date": str(frappe.db.get_value("Journal Entry", c.journal_entry, "posting_date")),\n                            "amount": due, "title": c.title or "Bill", "bill_date": str(c.bill_date or ""), "bill": c.bill or "",\n                            "account": c.expense_account or ""})\n        e["total"] = e["total"] + due\n        out[c.employee] = e\n    for a in frappe.get_all("Employee Advance", filters=af, fields=["name", "employee", "employee_name", "posting_date", "purpose", "advance_amount", "paid_amount"],\n                            order_by="posting_date asc", limit_page_length=0):\n        due = flt(a.advance_amount) - flt(a.paid_amount)\n        if due <= 0.005:\n            continue\n        e = out.get(a.employee) or {"employee": a.employee, "employee_name": a.employee_name, "claims": [], "advances": [], "total": 0}\n        e["advances"].append({"name": a.name, "date": str(a.posting_date), "purpose": a.purpose or "", "amount": due})\n        e["total"] = e["total"] + due\n        out[a.employee] = e\n    return out\n\n\ndef pay_entry(employee, to_account, refs, amount, bank, date, utr, company):\n    # one submitted Payment Entry: bank -> the employee, against refs [{doctype, name, amount}]\n    pe = frappe.get_doc({\n        "doctype": "Payment Entry",\n        "payment_type": "Pay",\n        "company": company,\n        "posting_date": date,\n        "party_type": "Employee",\n        "party": employee,\n        "paid_from": bank,\n        "paid_to": to_account,\n        "paid_amount": amount,\n        "received_amount": amount,\n        "source_exchange_rate": 1,\n        "target_exchange_rate": 1,\n        "reference_no": utr,\n        "reference_date": date,\n        "remarks": "Settlement payment, UTR " + utr,\n        "references": [],\n    })\n    for r in refs:\n        pe.append("references", {"reference_doctype": r["doctype"], "reference_name": r["name"], "allocated_amount": r["amount"]})\n    pe.insert()\n    pe.submit()\n    return pe.name\n\n\ndef pay_bills(employee, refs, amount, bank, date, utr, company, payable):\n    # one submitted Bank Entry: Dr 2120 against each bill\'s Journal Entry, Cr the bank\n    rows = []\n    for r in refs:\n        rows.append({"account": payable, "party_type": "Employee", "party": employee, "debit_in_account_currency": r["amount"],\n                     "reference_type": "Journal Entry", "reference_name": r["name"], "cost_center": "Main - ELPL"})\n    rows.append({"account": bank, "credit_in_account_currency": amount, "cost_center": "Main - ELPL"})\n    je = frappe.get_doc({"doctype": "Journal Entry", "voucher_type": "Bank Entry", "company": company, "posting_date": date,\n                         "cheque_no": utr, "cheque_date": date, "user_remark": "Settlement payment, UTR " + utr, "accounts": rows})\n    je.insert()\n    je.submit()\n    return je.name\n\n\ndef bill_payments(payable, since):\n    # the bills\' Bank Entries since a date: [{name, posting_date, party, party_name, paid_amount, reference_no, paid_to}]\n    out = []\n    for j in frappe.db.sql("""select je.name, je.posting_date, jea.party, sum(jea.debit_in_account_currency) as paid_amount, je.cheque_no as reference_no\n        from `tabJournal Entry` je join `tabJournal Entry Account` jea on jea.parent = je.name\n        where je.docstatus = 1 and je.voucher_type = \'Bank Entry\' and jea.account = %s and jea.party_type = \'Employee\'\n          and jea.debit_in_account_currency > 0 and jea.reference_type = \'Journal Entry\' and je.posting_date >= %s\n        group by je.name, jea.party order by je.posting_date desc limit 200""", (payable, since), as_dict=True):\n        out.append({"name": j.name, "posting_date": j.posting_date, "party": j.party,\n                    "party_name": frappe.db.get_value("Employee", j.party, "employee_name") or j.party,\n                    "paid_amount": j.paid_amount, "reference_no": j.reference_no or "", "paid_to": payable})\n    return out\n\n\ndef notify(user, subject, doctype, name):\n    try:\n        frappe.get_doc({"doctype": "Notification Log", "for_user": user, "type": "Alert", "subject": subject,\n                        "document_type": doctype, "document_name": name}).insert(ignore_permissions=True)\n    except Exception:\n        pass\n\n\nfd = frappe.form_dict\naction = str(fd.get("action") or "due")\nme = frappe.session.user\naccounts = me == "Administrator" or bool(frappe.db.get_value("Has Role", {"parent": me, "parenttype": "User", "role": ["in", ACCOUNTS_ROLES]}, "role"))\nif not accounts:\n    accounts = bool(frappe.db.exists("Project User", {"parent": ACCOUNTS_PROJECT, "parenttype": "Project", "user": me}))\nif not accounts:\n    frappe.throw("Paying employees is for Accounts.", frappe.PermissionError)\n\nif action == "due":\n    owe = owed(None, PAY)\n    rows = []\n    for e in owe:\n        x = owe[e]\n        emp = frappe.db.get_value("Employee", e, ["bank_name", "bank_ac_no", "ifsc_code", "custom_role_profile"], as_dict=True) or {}\n        x["bank_name"] = emp.get("bank_name") or ""\n        x["bank_ac_no"] = emp.get("bank_ac_no") or ""\n        x["ifsc"] = emp.get("ifsc_code") or ""\n        hq = ""\n        if emp.get("custom_role_profile"):\n            hq = str(frappe.db.get_value("Role Profile", emp.get("custom_role_profile"), "custom_territory") or "")\n        if hq[:3].upper() == "HQ-":\n            hq = hq[3:]\n        x["hq"] = hq\n        rows.append(x)\n    banks = frappe.get_all("Account", filters={"company": PAY["company"], "account_type": "Bank", "is_group": 0, "disabled": 0}, pluck="name", limit_page_length=50)\n    since = frappe.utils.add_days(frappe.utils.today(), -30)\n    paid = frappe.get_all("Payment Entry", filters=[["docstatus", "=", 1], ["party_type", "=", "Employee"], ["paid_to", "in", [PAY["payable"], PAY["advance"]]],\n                                                    ["posting_date", ">=", since]],\n                          fields=["name", "posting_date", "party", "party_name", "paid_amount", "reference_no", "paid_to"],\n                          order_by="posting_date desc, creation desc", limit_page_length=200)\n    # the bills are paid by Bank Entries (23 Nov 2026)\n    for j in bill_payments(PAY["payable"], since):\n        paid.append(j)\n    paid = sorted(paid, key=lambda x: str(x.get("posting_date")), reverse=True)\n    month_start = frappe.utils.get_first_day(frappe.utils.today())\n    paid_month = 0\n    paid_month_count = 0\n    for p in frappe.get_all("Payment Entry", filters=[["docstatus", "=", 1], ["party_type", "=", "Employee"], ["paid_to", "in", [PAY["payable"], PAY["advance"]]],\n                                                      ["posting_date", ">=", month_start]], fields=["paid_amount"], limit_page_length=0):\n        paid_month = paid_month + frappe.utils.flt(p.paid_amount)\n        paid_month_count = paid_month_count + 1\n    for j in bill_payments(PAY["payable"], month_start):\n        paid_month = paid_month + frappe.utils.flt(j["paid_amount"])\n        paid_month_count = paid_month_count + 1\n    frappe.response["message"] = {"employees": rows, "banks": banks, "default_bank": PAY["bank"], "paid": paid,\n                                  "paid_month": paid_month, "paid_month_count": paid_month_count, "today": frappe.utils.today(),\n                                  "user": frappe.get_fullname(me)}\n\nelif action == "pay":\n    want = []\n    for x in str(fd.get("employees") or "").split(","):\n        if x.strip() and x.strip() not in want:\n            want.append(x.strip())\n    if not want:\n        frappe.throw("Tick the employees you paid.")\n    bank = str(fd.get("bank_account") or PAY["bank"])\n    if frappe.db.get_value("Account", bank, "account_type") != "Bank":\n        frappe.throw(bank + " is not a bank account.")\n    date = str(fd.get("date") or frappe.utils.today())[:10]\n    common = " ".join(str(fd.get("utr") or "").split())[:140]\n    owe = owed(want, PAY)\n    done = []\n    missing = []\n    for e in want:\n        x = owe.get(e)\n        if not x:\n            continue\n        utr = " ".join(str(fd.get("utr_" + e) or "").split())[:140] or common\n        if not utr:\n            missing.append(x["employee_name"])\n            continue\n        crefs = []\n        camt = 0\n        for c in x["claims"]:\n            crefs.append({"name": c["entry"], "amount": c["amount"]})\n            camt = camt + c["amount"]\n        arefs = []\n        aamt = 0\n        for a in x["advances"]:\n            arefs.append({"doctype": "Employee Advance", "name": a["name"], "amount": a["amount"]})\n            aamt = aamt + a["amount"]\n        made = []\n        if crefs:\n            made.append(pay_bills(e, crefs, camt, bank, date, utr, PAY["company"], PAY["payable"]))\n        if arefs:\n            made.append(pay_entry(e, PAY["advance"], arefs, aamt, bank, date, utr, PAY["company"]))\n        # the bills paid in full are Paid (the app shows it to the employee)\n        for c in x["claims"]:\n            if left_on(c["entry"], e, PAY["payable"]) <= 0.005:\n                frappe.db.set_value("Settlement Expense", c["name"], "status", "Paid")\n        done.append({"employee": e, "employee_name": x["employee_name"], "amount": camt + aamt, "entries": made, "utr": utr})\n        u = frappe.db.get_value("Employee", e, "user_id")\n        if u:\n            notify(u, "Paid to your bank: " + frappe.utils.fmt_money(camt + aamt, currency="INR") + " (ref " + utr + ")",\n                   "Journal Entry" if crefs else "Payment Entry", made[0])\n    if missing and not done:\n        frappe.throw("Give the UTR of the payment for: " + ", ".join(missing))\n    frappe.response["message"] = {"paid": done, "missing_utr": missing}\n\nelse:\n    frappe.throw("Unknown action.")\n'
REPORT_SRC = '# Report "Settlement To Pay" -- Script Report (not standard), ref Settlement Expense\n# (18 Nov 2026). For Accounts, in the ERP (management: paying is Accounts\'\n# work in the ERP, not in the app): ONE ROW PER EMPLOYEE with what the CEO\n# approved and is not paid yet --\n#   bills   Settlement Expenses the CEO approved, each booked as ONE Journal\n#           Entry (23 Nov 2026; was an Expense Claim) whose credit on 2120\n#           Employee Expense Payable is not paid yet\n#   cash    submitted Employee Advances on "Employee Expense Advances", Unpaid\n# -- with the employee\'s bank details for the bank upload (Export -> Excel).\n#\n# Paying: the Settlement Payments page (/settlement-payments) -- per employee a\n# Bank Entry (Journal Entry) against each bill\'s Journal Entry (ERPNext takes no\n# Payment Entry against a Journal Entry owed to an employee), and it marks the\n# bills Paid. A cash advance: open it -> Payment.\n#\n# Report script (safe_exec, locals apart): no comprehensions over local\n# names, no defs; the answer is `data = [columns, rows]`.\n\nPAYABLE = "2120 - Employee Expense Payable - ELPL"\nADVANCE = "Employee Expense Advances - ELPL"\ncolumns = [\n    {"fieldname": "employee", "label": "Employee", "fieldtype": "Link", "options": "Employee", "width": 110},\n    {"fieldname": "employee_name", "label": "Name", "fieldtype": "Data", "width": 190},\n    {"fieldname": "hq", "label": "HQ", "fieldtype": "Data", "width": 110},\n    {"fieldname": "bills", "label": "Bills", "fieldtype": "Int", "width": 70},\n    {"fieldname": "bills_amount", "label": "Bills (Rs)", "fieldtype": "Currency", "width": 120},\n    {"fieldname": "advances", "label": "Cash Advances", "fieldtype": "Int", "width": 110},\n    {"fieldname": "advance_amount", "label": "Advances (Rs)", "fieldtype": "Currency", "width": 120},\n    {"fieldname": "total", "label": "To Pay (Rs)", "fieldtype": "Currency", "width": 130},\n    {"fieldname": "oldest", "label": "Waiting Since", "fieldtype": "Date", "width": 115},\n    {"fieldname": "bank_name", "label": "Bank", "fieldtype": "Data", "width": 160},\n    {"fieldname": "bank_ac_no", "label": "Account No", "fieldtype": "Data", "width": 150},\n    {"fieldname": "ifsc", "label": "IFSC", "fieldtype": "Data", "width": 115},\n    {"fieldname": "bank_ok", "label": "Bank Details", "fieldtype": "Data", "width": 110},\n]\nby = {}\nfor c in frappe.get_all("Settlement Expense", filters={"status": "Verified", "journal_entry": ["is", "set"], "payable": [">", 0]},\n                        fields=["employee", "employee_name", "journal_entry", "modified"], limit_page_length=0):\n    # still owed on the bill\'s Journal Entry (Payment Ledger)\n    led = frappe.db.sql("""select sum(amount_in_account_currency) from `tabPayment Ledger Entry`\n        where against_voucher_type = \'Journal Entry\' and against_voucher_no = %s and party_type = \'Employee\'\n          and party = %s and account = %s and delinked = 0""", (c.journal_entry, c.employee, PAYABLE))\n    s = frappe.utils.flt(led[0][0] if led and led[0] else 0)\n    due = -s if s < 0 else s\n    if due <= 0.005:\n        continue\n    c.posting_date = frappe.db.get_value("Journal Entry", c.journal_entry, "posting_date")\n    r = by.get(c.employee) or {"employee": c.employee, "employee_name": c.employee_name, "bills": 0, "bills_amount": 0,\n                               "advances": 0, "advance_amount": 0, "total": 0, "oldest": None}\n    r["bills"] = r["bills"] + 1\n    r["bills_amount"] = r["bills_amount"] + due\n    r["total"] = r["total"] + due\n    if not r["oldest"] or str(c.posting_date) < str(r["oldest"]):\n        r["oldest"] = c.posting_date\n    by[c.employee] = r\nfor a in frappe.get_all("Employee Advance", filters={"docstatus": 1, "status": "Unpaid", "advance_account": ADVANCE},\n                        fields=["employee", "employee_name", "posting_date", "advance_amount", "paid_amount"], limit_page_length=0):\n    due = frappe.utils.flt(a.advance_amount) - frappe.utils.flt(a.paid_amount)\n    if due <= 0.005:\n        continue\n    r = by.get(a.employee) or {"employee": a.employee, "employee_name": a.employee_name, "bills": 0, "bills_amount": 0,\n                               "advances": 0, "advance_amount": 0, "total": 0, "oldest": None}\n    r["advances"] = r["advances"] + 1\n    r["advance_amount"] = r["advance_amount"] + due\n    r["total"] = r["total"] + due\n    if not r["oldest"] or str(a.posting_date) < str(r["oldest"]):\n        r["oldest"] = a.posting_date\n    by[a.employee] = r\nrows = []\nfor e in by:\n    r = by[e]\n    emp = frappe.db.get_value("Employee", e, ["bank_name", "bank_ac_no", "ifsc_code", "custom_role_profile"], as_dict=True) or {}\n    r["bank_name"] = emp.get("bank_name") or ""\n    r["bank_ac_no"] = emp.get("bank_ac_no") or ""\n    r["ifsc"] = emp.get("ifsc_code") or ""\n    r["bank_ok"] = "OK" if (r["bank_ac_no"] and r["ifsc"]) else "MISSING"\n    hq = ""\n    if emp.get("custom_role_profile"):\n        hq = str(frappe.db.get_value("Role Profile", emp.get("custom_role_profile"), "custom_territory") or "")\n    if hq[:3].upper() == "HQ-":\n        hq = hq[3:]\n    r["hq"] = hq\n    rows.append(r)\n# the biggest amounts first\nordered = []\nwhile rows:\n    k = 0\n    i = 1\n    while i < len(rows):\n        if rows[i]["total"] > rows[k]["total"]:\n            k = i\n        i = i + 1\n    ordered.append(rows.pop(k))\ndata = [columns, ordered]\n'
PAGE = {'main_section_html': '<div id="sp" class="sp">\n  <header class="sp-head">\n    <div>\n      <nav class="sp-crumb"><a href="/app/dashboards">Dashboards</a><span>/</span>Settlement Payments</nav>\n      <h1>Settlement Payments</h1>\n      <p class="sp-lede" data-sub>Loading…</p>\n    </div>\n    <div class="sp-head-actions">\n      <a class="sp-btn" href="/app/query-report/Settlement%20To%20Pay" target="_blank">Settlement To Pay report</a>\n      <a class="sp-btn" href="/app/payment-entry?party_type=Employee" target="_blank">Payment entries</a>\n      <button class="sp-btn sp-icon" data-reload title="Refresh" aria-label="Refresh">\n        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 11a8 8 0 1 0-2.3 5.7M20 4v7h-7"/></svg>\n      </button>\n    </div>\n  </header>\n\n  <section class="sp-summary" aria-label="Summary">\n    <div class="sp-figs">\n      <div class="sp-fig sp-fig-lead"><span>Outstanding</span><b data-k="total">–</b><small data-k="total_sub"></small></div>\n      <div class="sp-fig"><span>Bills</span><b data-k="bills">–</b><small data-k="bills_sub"></small></div>\n      <div class="sp-fig"><span>Cash advances</span><b data-k="adv">–</b><small data-k="adv_sub"></small></div>\n      <div class="sp-fig"><span>Paid this month</span><b data-k="paid">–</b><small data-k="paid_sub"></small></div>\n    </div>\n    <div class="sp-ageing">\n      <div class="sp-ageing-head"><span>Ageing since approval</span><button class="sp-link" data-age-clear hidden>Show all</button></div>\n      <div class="sp-ageing-bar" data-agebar></div>\n      <div class="sp-ageing-keys" data-agekeys></div>\n    </div>\n  </section>\n\n  <div class="sp-main">\n    <section class="sp-panel sp-register">\n      <div class="sp-panel-head">\n        <div><h2>Payable to employees</h2><p class="sp-note" data-regnote></p></div>\n        <label class="sp-search"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/></svg><input data-q placeholder="Employee, ID or HQ" aria-label="Search"></label>\n      </div>\n      <div class="sp-scroll">\n        <table class="sp-table">\n          <thead>\n            <tr>\n              <th class="c"><input type="checkbox" data-all aria-label="Tick everyone shown"></th>\n              <th>Employee</th>\n              <th>HQ</th>\n              <th class="r">Bills</th>\n              <th class="r">Cash advance</th>\n              <th>Waiting</th>\n              <th>Bank account</th>\n              <th class="r">To pay</th>\n            </tr>\n          </thead>\n          <tbody data-rows><tr><td colspan="8" class="sp-empty">Loading…</td></tr></tbody>\n        </table>\n      </div>\n    </section>\n\n    <aside class="sp-panel sp-run" aria-label="Payment run">\n      <div class="sp-run-head">\n        <h2>Payment run</h2>\n        <b class="sp-run-total" data-runtotal>₹0.00</b>\n        <p class="sp-note" data-runinfo>Tick employees in the list to add them.</p>\n      </div>\n      <ul class="sp-run-list" data-runlist></ul>\n      <p class="sp-warn" data-runwarn hidden></p>\n      <div class="sp-run-form">\n        <label>Paid from<select data-bank></select></label>\n        <label>Value date<input type="date" data-date></label>\n        <label>UTR for the run<input data-utr placeholder="Bank reference of the bulk upload"></label>\n        <p class="sp-hint">Paid one by one? Leave this empty and type each person\'s UTR above.</p>\n      </div>\n      <div class="sp-run-actions">\n        <button class="sp-btn sp-block" data-csv disabled>Download bank file</button>\n        <button class="sp-btn sp-primary sp-block" data-pay disabled>Record payment</button>\n        <p class="sp-hint">Record only after the money has left the bank. The ERP makes the Payment Entries and tells each employee.</p>\n      </div>\n    </aside>\n  </div>\n\n  <section class="sp-panel">\n    <div class="sp-panel-head"><div><h2>Paid in the last 30 days</h2></div></div>\n    <div class="sp-scroll">\n      <table class="sp-table">\n        <thead><tr><th>Value date</th><th>Employee</th><th>For</th><th>UTR</th><th>Payment entry</th><th class="r">Amount</th></tr></thead>\n        <tbody data-paid></tbody>\n      </table>\n    </div>\n  </section>\n\n  <div class="sp-modal" data-modal hidden>\n    <div class="sp-dialog" role="dialog" aria-modal="true">\n      <h3 data-mtitle></h3>\n      <div data-mbody></div>\n      <div class="sp-mfoot">\n        <button class="sp-btn" data-mno>Cancel</button>\n        <button class="sp-btn sp-primary" data-myes>OK</button>\n      </div>\n    </div>\n  </div>\n</div>\n', 'javascript': '// Web Page "settlement-payments" (/settlement-payments) -- SCRIPT (18 Nov 2026).\n// Accounts\' dashboard for paying settlement bills, listed on the Dashboards\n// workspace next to Field Expenses. Everything for this one process in one\n// place: what is owed (bills the CEO approved, already booked on 2120, and\n// cash advances) with its ageing, the payment run (bank file, UTR, record\n// payment -- the ERP makes the Payment Entries), and what was paid. Data +\n// actions: Server Script "Settlement Accounts API" (/api/method/settlement_accounts).\n(function () {\n  function start() {\n    var root = document.getElementById("sp");\n    if (!root) return;\n    var $ = function (s) { return root.querySelector(s); };\n    var esc = function (s) { return String(s == null ? "" : s).replace(/[&<>"\']/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", \'"\': "&quot;", "\'": "&#39;" }[c]; }); };\n    var inr = new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 2, minimumFractionDigits: 2 });\n    var money = function (v) { return inr.format(v || 0); };\n    // a payment: the bills\' Bank Entry is a Journal Entry (ACC-JV-), an advance\'s a Payment Entry (23 Nov 2026)\n    var docUrl = function (n) { return (/^ACC-JV-/.test(String(n)) ? "/app/journal-entry/" : "/app/payment-entry/") + encodeURIComponent(n); };\n    var MON = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];\n    var dfmt = function (d) { if (!d) return ""; var p = String(d).slice(0, 10).split("-"); return p[2] + " " + MON[+p[1] - 1] + " " + p[0]; };\n    var plural = function (n, w, ws) { return n + " " + (n === 1 ? w : (ws || w + "s")); };\n    var today = new Date().toISOString().slice(0, 10);\n    var rows = [], picked = {}, open = {}, utrs = {}, query = "", ageOn = null;\n    // ageing bands, days since the CEO\'s approval (= the booking date)\n    var AGES = [\n      { label: "0–7 days", max: 7, color: "var(--a1)" },\n      { label: "8–15 days", max: 15, color: "var(--a2)" },\n      { label: "16–30 days", max: 30, color: "var(--a3)" },\n      { label: "Over 30 days", max: 1e9, color: "var(--a4)" },\n    ];\n    var daysOf = function (d) { return d ? Math.max(0, Math.round((new Date(today) - new Date(String(d).slice(0, 10))) / 864e5)) : 0; };\n    var bandOf = function (d) { var n = daysOf(d); for (var i = 0; i < AGES.length; i++) if (n <= AGES[i].max) return i; return AGES.length - 1; };\n    var items = function (r) { return r.claims.concat(r.advances); };\n    var since = function (r) { var d = ""; items(r).forEach(function (x) { if (!d || x.date < d) d = x.date; }); return d; };\n    var last4 = function (s) { s = String(s || ""); return s.length > 4 ? "••" + s.slice(-4) : s; };\n\n    function api(method, params) {\n      var hdr = { Accept: "application/json" };\n      var opt = { credentials: "same-origin", headers: hdr };\n      var url = "/api/method/settlement_accounts";\n      if (method === "GET") url += "?" + new URLSearchParams(params).toString();\n      else {\n        hdr["Content-Type"] = "application/x-www-form-urlencoded";\n        if (window.frappe && window.frappe.csrf_token) hdr["X-Frappe-CSRF-Token"] = window.frappe.csrf_token;\n        opt.method = "POST";\n        opt.body = new URLSearchParams(params).toString();\n      }\n      return fetch(url, opt).then(function (r) {\n        return r.json().catch(function () { return {}; }).then(function (j) {\n          if (r.ok) return j.message || {};\n          var msg = "";\n          try { msg = JSON.parse(JSON.parse(j._server_messages)[0]).message; } catch (e) { msg = j.exception || ("Error " + r.status); }\n          var err = new Error(String(msg).replace(/<[^>]+>/g, ""));\n          err.denied = r.status === 403 || j.exc_type === "PermissionError";\n          throw err;\n        });\n      });\n    }\n\n    // ---- dialogs (the website has no frappe.confirm / msgprint)\n    function dialog(title, html, yesText, onYes, wide) {\n      $(".sp-dialog").classList.toggle("sp-wide", !!wide);\n      $("[data-mtitle]").textContent = title;\n      $("[data-mbody]").innerHTML = html;\n      $("[data-myes]").textContent = yesText || "OK";\n      $("[data-mno]").hidden = !onYes;\n      $("[data-modal]").hidden = false;\n      $("[data-myes]").onclick = function () { $("[data-modal]").hidden = true; if (onYes) onYes(); };\n      $("[data-mno]").onclick = function () { $("[data-modal]").hidden = true; };\n      $("[data-myes]").focus();\n    }\n\n    function load() {\n      $("[data-sub]").textContent = "Loading…";\n      return api("GET", { action: "due" }).then(function (m) {\n        rows = (m.employees || []).sort(function (a, b) { return b.total - a.total; });\n        Object.keys(picked).forEach(function (id) { if (!rows.some(function (x) { return x.employee === id; })) delete picked[id]; });\n        if (m.today) today = m.today;\n        if (!$("[data-date]").value) $("[data-date]").value = today;\n        var sel = $("[data-bank]"), keep = sel.value;\n        sel.innerHTML = (m.banks || []).map(function (b) { return \'<option value="\' + esc(b) + \'">\' + esc(b.replace(/ - ELPL$/, "")) + "</option>"; }).join("");\n        sel.value = keep || m.default_bank || (m.banks || [])[0] || "";\n        summary(m);\n        render();\n        renderPaid(m.paid || []);\n      }).catch(function (e) {\n        if (e.denied) {\n          root.innerHTML = \'<div class="sp-panel sp-empty"><h2>This page is for the Accounts team</h2><p class="sp-note">Log in with your Accounts login to pay settlements.</p>\'\n            + \'<p><a class="sp-btn sp-primary" href="/login?redirect-to=/settlement-payments">Log in</a></p></div>\';\n        } else $("[data-sub]").textContent = "Could not load: " + e.message + " — press Refresh.";\n      });\n    }\n\n    function summary(m) {\n      var total = 0, bills = 0, billsAmt = 0, adv = 0, advAmt = 0, oldest = "";\n      rows.forEach(function (r) {\n        total += r.total;\n        r.claims.forEach(function (c) { bills++; billsAmt += c.amount; });\n        r.advances.forEach(function (a) { adv++; advAmt += a.amount; });\n        var s = since(r);\n        if (s && (!oldest || s < oldest)) oldest = s;\n      });\n      $(\'[data-k="total"]\').textContent = money(total);\n      $(\'[data-k="total_sub"]\').textContent = rows.length ? plural(rows.length, "employee") + (oldest ? " · oldest " + plural(daysOf(oldest), "day") : "") : "Nothing to pay";\n      $(\'[data-k="bills"]\').textContent = money(billsAmt);\n      $(\'[data-k="bills_sub"]\').textContent = plural(bills, "bill");\n      $(\'[data-k="adv"]\').textContent = money(advAmt);\n      $(\'[data-k="adv_sub"]\').textContent = plural(adv, "advance");\n      $(\'[data-k="paid"]\').textContent = money(m.paid_month);\n      $(\'[data-k="paid_sub"]\').textContent = plural(m.paid_month_count || 0, "payment entry", "payment entries");\n      $("[data-sub]").textContent = rows.length\n        ? "Employee bills and cash advances approved by the CEO, booked to 2120 Employee Expense Payable and waiting for payment."\n        : "Nothing to pay. Approved bills appear here as soon as the CEO approves them.";\n    }\n\n    function ageing() {\n      var amt = [0, 0, 0, 0], total = 0;\n      rows.forEach(function (r) { items(r).forEach(function (x) { amt[bandOf(x.date)] += x.amount; total += x.amount; }); });\n      var bar = $("[data-agebar]");\n      bar.classList.toggle("filtered", ageOn !== null);\n      bar.innerHTML = total ? AGES.map(function (a, i) {\n        return amt[i] ? \'<button data-age="\' + i + \'" class="\' + (ageOn === i ? "on" : "") + \'" style="flex:\' + amt[i] + ";background:" + a.color + \'" title="\' + esc(a.label + " · " + money(amt[i])) + \'" aria-label="\' + esc("Show " + a.label) + \'"></button>\' : "";\n      }).join("") : "";\n      $("[data-agekeys]").innerHTML = AGES.map(function (a, i) {\n        return \'<button class="sp-key\' + (ageOn === i ? " on" : "") + \'" data-age="\' + i + \'"\' + (amt[i] ? "" : " disabled") + \'><i style="background:\' + a.color + \'"></i>\' + esc(a.label) + " <b>" + money(amt[i]) + "</b></button>";\n      }).join("");\n      $("[data-age-clear]").hidden = ageOn === null;\n    }\n\n    function shown() {\n      return rows.filter(function (r) {\n        if (query && (r.employee_name + " " + r.employee + " " + r.hq).toLowerCase().indexOf(query) < 0) return false;\n        if (ageOn !== null && !items(r).some(function (x) { return bandOf(x.date) === ageOn; })) return false;\n        return true;\n      });\n    }\n\n    var CARET = \'<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 6l6 6-6 6"/></svg>\';\n\n    function rowHtml(r) {\n      var on = !!picked[r.employee], bankOk = r.bank_ac_no && r.ifsc;\n      var bAmt = r.claims.reduce(function (s, c) { return s + c.amount; }, 0);\n      var aAmt = r.advances.reduce(function (s, a) { return s + a.amount; }, 0);\n      var d = since(r), n = daysOf(d), band = AGES[bandOf(d)];\n      var main = \'<tr class="sp-row\' + (on ? " on" : "") + \'">\'\n        + \'<td class="c"><input type="checkbox" data-pick="\' + esc(r.employee) + \'"\' + (on ? " checked" : "") + \' aria-label="\' + esc("Pay " + r.employee_name) + \'"></td>\'\n        + \'<td><div class="sp-who"><button class="sp-caret\' + (open[r.employee] ? " open" : "") + \'" data-open="\' + esc(r.employee) + \'" aria-expanded="\' + !!open[r.employee] + \'" aria-label="\' + esc("Show " + r.employee_name + "\'s documents") + \'">\' + CARET + "</button>"\n        + \'<div><span class="sp-name">\' + esc(r.employee_name) + \'</span><span class="sp-sub mono">\' + esc(r.employee) + "</span></div></div></td>"\n        + "<td>" + esc(r.hq || "–") + "</td>"\n        + \'<td class="r">\' + (r.claims.length ? \'<span class="sp-amt">\' + money(bAmt) + \'</span><span class="sp-sub">\' + plural(r.claims.length, "bill") + "</span>" : \'<span class="sp-sub">–</span>\') + "</td>"\n        + \'<td class="r">\' + (r.advances.length ? \'<span class="sp-amt">\' + money(aAmt) + "</span>" : \'<span class="sp-sub">–</span>\') + "</td>"\n        + \'<td><span class="sp-age"><i style="background:\' + band.color + \'"></i>\' + plural(n, "day") + \'</span><span class="sp-sub">since \' + dfmt(d) + "</span></td>"\n        + "<td>" + (bankOk ? esc(r.bank_name || "Bank") + \'<span class="sp-sub mono" title="\' + esc(r.bank_ac_no) + \'">\' + esc(last4(r.bank_ac_no)) + " · " + esc(r.ifsc) + "</span>"\n          : \'<span class="sp-nobank">No bank details</span><span class="sp-sub">Ask HR to add them</span>\') + "</td>"\n        + \'<td class="r sp-total">\' + money(r.total) + "</td></tr>";\n      if (!open[r.employee]) return main;\n      var docs = r.claims.map(function (c) {\n        return \'<tr class="sp-doc"><td></td><td colspan="4"><span class="sp-tag">Bill</span><b>\' + esc(c.title) + \'</b> <span class="sp-sub" style="display:inline">· \' + dfmt(c.bill_date || c.date) + " · " + esc((c.account || "").replace(/ - ELPL$/, "")) + "</span></td>"\n          + \'<td><span class="sp-sub" style="display:inline">approved \' + dfmt(c.date) + "</span></td>"\n          + \'<td><span class="sp-doclinks"><a class="mono" href="/app/settlement-expense/\' + encodeURIComponent(c.name) + \'" target="_blank">\' + esc(c.name) + "</a>"\n          + (c.entry ? \'<a class="mono" href="/app/journal-entry/\' + encodeURIComponent(c.entry) + \'" target="_blank">\' + esc(c.entry) + "</a>" : "")\n          + (c.bill ? \'<a href="\' + esc(c.bill) + \'" data-photo="\' + esc(c.bill) + \'" data-ptitle="\' + esc(r.employee_name + " · " + c.title + " · " + money(c.amount)) + \'" data-claim="\' + esc(c.name) + \'">Bill photo</a>\' : "") + "</span></td>"\n          + \'<td class="r sp-amt">\' + money(c.amount) + "</td></tr>";\n      }).concat(r.advances.map(function (a) {\n        return \'<tr class="sp-doc"><td></td><td colspan="4"><span class="sp-tag">Advance</span><b>\' + esc(a.purpose || "Cash advance") + "</b></td>"\n          + \'<td><span class="sp-sub" style="display:inline">approved \' + dfmt(a.date) + "</span></td>"\n          + \'<td><a class="mono" href="/app/employee-advance/\' + encodeURIComponent(a.name) + \'" target="_blank">\' + esc(a.name) + "</a></td>"\n          + \'<td class="r sp-amt">\' + money(a.amount) + "</td></tr>";\n      })).join("");\n      return main + docs;\n    }\n\n    function render() {\n      ageing();\n      var list = shown();\n      var body = $("[data-rows]");\n      if (!list.length) {\n        body.innerHTML = \'<tr><td colspan="8" class="sp-empty">\' + (rows.length ? "No one matches. Clear the search or the ageing filter." : "Nothing to pay. Approved bills appear here as soon as the CEO approves them.") + "</td></tr>";\n      } else body.innerHTML = list.map(rowHtml).join("");\n      $("[data-regnote]").textContent = rows.length ? (list.length === rows.length ? plural(rows.length, "employee") + ", largest first" : list.length + " of " + plural(rows.length, "employee") + " shown") : "";\n      $("[data-all]").checked = list.length > 0 && list.every(function (r) { return picked[r.employee]; });\n      run();\n    }\n\n    // the payment run: who is ticked, their UTRs, and the total\n    function run() {\n      var sel = rows.filter(function (r) { return picked[r.employee]; });\n      var amt = sel.reduce(function (s, r) { return s + r.total; }, 0);\n      $("[data-runtotal]").textContent = money(amt);\n      $("[data-runinfo]").textContent = sel.length ? plural(sel.length, "employee") + " in this run" : "Tick employees in the list to add them.";\n      var noBank = sel.filter(function (r) { return !(r.bank_ac_no && r.ifsc); });\n      $("[data-runlist]").innerHTML = sel.map(function (r) {\n        return "<li><span><b>" + esc(r.employee_name) + \'</b><span class="sp-sub">\' + esc(r.bank_name || "No bank details") + (r.bank_ac_no ? " " + esc(last4(r.bank_ac_no)) : "") + "</span></span>"\n          + \'<span class="sp-amt">\' + money(r.total) + "</span>"\n          + \'<input data-utr-for="\' + esc(r.employee) + \'" value="\' + esc(utrs[r.employee] || "") + \'" placeholder="Own UTR (if paid separately)" aria-label="\' + esc("UTR for " + r.employee_name) + \'">\'\n          + \'<button class="sp-x" data-unpick="\' + esc(r.employee) + \'">Remove</button></li>\';\n      }).join("");\n      $("[data-runwarn]").hidden = !noBank.length;\n      $("[data-runwarn]").textContent = noBank.length ? noBank.map(function (r) { return r.employee_name; }).join(", ") + " " + (noBank.length === 1 ? "has" : "have") + " no bank details in the ERP — the bank file leaves them empty." : "";\n      $("[data-pay]").textContent = sel.length ? "Record payment · " + money(amt) : "Record payment";\n      $("[data-pay]").disabled = !sel.length;\n      $("[data-csv]").disabled = !sel.length;\n    }\n\n    function renderPaid(paid) {\n      $("[data-paid]").innerHTML = paid.length ? paid.map(function (p) {\n        return "<tr><td>" + dfmt(p.posting_date) + \'</td><td><span class="sp-name">\' + esc(p.party_name || p.party) + \'</span><span class="sp-sub mono">\' + esc(p.party) + "</span></td>"\n          + "<td>" + (String(p.paid_to || "").indexOf("Advance") >= 0 ? "Cash advance" : "Bills") + "</td>"\n          + \'<td class="mono">\' + esc(p.reference_no) + "</td>"\n          + \'<td><a class="mono" href="\' + docUrl(p.name) + \'" target="_blank">\' + esc(p.name) + "</a></td>"\n          + \'<td class="r sp-amt">\' + money(p.paid_amount) + "</td></tr>";\n      }).join("") : \'<tr><td colspan="6" class="sp-empty">No payments recorded in the last 30 days.</td></tr>\';\n    }\n\n    function bankFile() {\n      var sel = rows.filter(function (r) { return picked[r.employee]; });\n      var q = function (v) { return \'"\' + String(v == null ? "" : v).replace(/"/g, \'""\') + \'"\'; };\n      var lines = [["Name", "Employee", "Account number", "IFSC", "Bank", "Amount", "Narration"]];\n      sel.forEach(function (r) { lines.push([r.employee_name, r.employee, r.bank_ac_no, r.ifsc, r.bank_name, r.total.toFixed(2), "Elbrit settlement " + today]); });\n      var blob = new Blob([lines.map(function (l) { return l.map(q).join(","); }).join("\\r\\n")], { type: "text/csv" });\n      var a = document.createElement("a");\n      a.href = URL.createObjectURL(blob);\n      a.download = "settlement-bank-file-" + today + ".csv";\n      document.body.appendChild(a);\n      a.click();\n      a.remove();\n      var missing = sel.filter(function (r) { return !(r.bank_ac_no && r.ifsc); }).map(function (r) { return esc(r.employee_name); });\n      if (missing.length) dialog("Bank details missing", "The ERP has no bank account or IFSC for <b>" + missing.join(", ") + "</b>. Their rows in the file are empty — ask HR to fill them in the Employee record, or pay them separately.");\n    }\n\n    function pay() {\n      var sel = rows.filter(function (r) { return picked[r.employee]; });\n      if (!sel.length) return;\n      var common = $("[data-utr]").value.trim();\n      var date = $("[data-date]").value || today;\n      var params = { action: "pay", employees: sel.map(function (r) { return r.employee; }).join(","), bank_account: $("[data-bank]").value, date: date, utr: common };\n      var noUtr = [];\n      sel.forEach(function (r) {\n        var v = (utrs[r.employee] || "").trim();\n        if (v) params["utr_" + r.employee] = v;\n        else if (!common) noUtr.push(esc(r.employee_name));\n      });\n      if (noUtr.length) return dialog("UTR needed", "Type the bank reference (UTR) once in <b>UTR for the run</b>, or on the line of: <b>" + noUtr.join(", ") + "</b>.");\n      var amt = sel.reduce(function (s, r) { return s + r.total; }, 0);\n      dialog("Record this payment?",\n        "<p><b>" + money(amt) + "</b> to <b>" + plural(sel.length, "employee") + "</b>, paid from <b>" + esc(params.bank_account.replace(/ - ELPL$/, "")) + "</b> on <b>" + dfmt(date) + "</b>.</p>"\n        + "<table>" + sel.map(function (r) { return "<tr><td>" + esc(r.employee_name) + \'</td><td class="mono">UTR \' + esc(params["utr_" + r.employee] || common) + \'</td><td class="mono" style="text-align:right">\' + money(r.total) + "</td></tr>"; }).join("") + "</table>"\n        + \'<p class="sp-note">Do this only after the money has left the bank. The ERP makes the Payment Entries, the bills turn Paid and each employee is told.</p>\',\n        "Record payment", function () {\n          $("[data-pay]").disabled = true;\n          $("[data-pay]").textContent = "Recording…";\n          api("POST", params).then(function (m) {\n            picked = {};\n            utrs = {};\n            var done = m.paid || [];\n            dialog("Payment recorded",\n              "<table>" + done.map(function (d) {\n                return "<tr><td><b>" + esc(d.employee_name) + \'</b></td><td class="mono">\' + d.entries.map(function (e) { return \'<a href="\' + docUrl(e) + \'" target="_blank">\' + esc(e) + "</a>"; }).join(", ")\n                  + \'</td><td class="mono" style="text-align:right">\' + money(d.amount) + "</td></tr>";\n              }).join("") + "</table>"\n              + (m.missing_utr && m.missing_utr.length ? "<p>Not recorded (no UTR): " + m.missing_utr.map(esc).join(", ") + "</p>" : ""));\n            load();\n          }).catch(function (e) {\n            dialog("Not recorded", esc(e.message) + "<p class=\'sp-note\'>Nothing was saved for the employee this stopped at. Check and try again.</p>");\n            load();\n          });\n        });\n    }\n\n    // the bill opens in a popup on this page (an image, or a PDF in a viewer)\n    function photo(a) {\n      var url = a.getAttribute("data-photo"), claim = a.getAttribute("data-claim");\n      var pdf = /\\.pdf($|\\?)/i.test(url);\n      var body = (pdf ? \'<iframe class="sp-pdf" src="\' + esc(url) + \'"></iframe>\'\n                      : \'<div class="sp-photo"><img src="\' + esc(url) + \'" alt="bill"></div>\')\n        + \'<p class="sp-note"><a href="\' + esc(url) + \'" target="_blank">Open full size</a> · <a href="/app/settlement-expense/\' + encodeURIComponent(claim) + \'" target="_blank">Bill \' + esc(claim) + "</a></p>";\n      dialog(a.getAttribute("data-ptitle"), body, "Close", null, true);\n      var img = $(".sp-photo img");\n      if (img) img.onerror = function () { img.parentNode.innerHTML = \'<p class="sp-bad">The photo could not be shown here — use "Open full size".</p>\'; };\n    }\n\n    root.addEventListener("click", function (ev) {\n      var t = ev.target;\n      var o = t.closest("[data-open]"), ph = t.closest("[data-photo]"), ag = t.closest("[data-age]"), un = t.closest("[data-unpick]");\n      if (ph) { ev.preventDefault(); photo(ph); }\n      else if (o) { var id = o.getAttribute("data-open"); if (open[id]) delete open[id]; else open[id] = 1; render(); }\n      else if (ag) { var i = +ag.getAttribute("data-age"); ageOn = ageOn === i ? null : i; render(); }\n      else if (un) { delete picked[un.getAttribute("data-unpick")]; render(); }\n      else if (t.closest("[data-age-clear]")) { ageOn = null; render(); }\n      else if (t.closest("[data-reload]")) load();\n      else if (t.closest("[data-csv]")) bankFile();\n      else if (t.closest("[data-pay]")) pay();\n      else if (t === $("[data-modal]")) $("[data-modal]").hidden = true;\n    });\n    root.addEventListener("change", function (ev) {\n      var t = ev.target;\n      if (t.matches("[data-pick]")) {\n        var id = t.getAttribute("data-pick");\n        if (t.checked) picked[id] = 1; else delete picked[id];\n        render();\n      } else if (t.matches("[data-all]")) {\n        shown().forEach(function (r) { if (t.checked) picked[r.employee] = 1; else delete picked[r.employee]; });\n        render();\n      }\n    });\n    root.addEventListener("input", function (ev) {\n      if (ev.target.matches("[data-utr-for]")) utrs[ev.target.getAttribute("data-utr-for")] = ev.target.value;\n    });\n    document.addEventListener("keydown", function (ev) { if (ev.key === "Escape") $("[data-modal]").hidden = true; });\n    $("[data-q]").addEventListener("input", function (ev) { query = ev.target.value.trim().toLowerCase(); render(); });\n    load();\n  }\n  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", start); else start();\n})();\n', 'css': '@import url("https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500&family=IBM+Plex+Sans:wght@400;500;600&display=swap");\n.web-page-content{max-width:none;padding:0}.page-header-wrapper{display:none}\nbody{background:#f4f5f7}\n.sp{--ink:#15191e;--ink2:#4a5260;--ink3:#8a929e;--rule:#e4e7eb;--rule2:#eef0f3;--canvas:#f4f5f7;--paper:#fff;\n  --brand:#d92c24;--brand-dark:#b8231c;--brand-text:#a81c16;--good:#1f7a4d;--warn:#9a5b00;\n  --a1:#3b7a6b;--a2:#c9971c;--a3:#c2611f;--a4:#6e2b12;\n  --sans:"IBM Plex Sans",system-ui,-apple-system,"Segoe UI",sans-serif;--mono:"IBM Plex Mono",ui-monospace,"SFMono-Regular",Consolas,monospace;\n  font-family:var(--sans);color:var(--ink);font-size:14px;line-height:1.45;max-width:1360px;margin:0 auto;padding:22px 24px 64px}\n.sp *{box-sizing:border-box}\n.sp [hidden]{display:none!important}\n.sp a{color:#1f4fbf;text-decoration:none}.sp a:hover{text-decoration:underline}\n.sp :focus-visible{outline:2px solid #1f4fbf;outline-offset:2px}\n.sp .mono{font-family:var(--mono);font-size:.94em;letter-spacing:-.01em}\n.sp a.sp-btn{color:var(--ink)}\n.sp a.sp-primary{color:#fff}\n\n/* head */\n.sp-head{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;flex-wrap:wrap;margin-bottom:18px}\n.sp-crumb{font-size:12px;color:var(--ink3);display:flex;gap:6px;margin-bottom:4px}.sp-crumb a{color:var(--ink3)}\n.sp h1{font-size:24px;font-weight:600;margin:0;letter-spacing:-.015em}\n.sp h2{font-size:15px;font-weight:600;margin:0}\n.sp h3{font-size:16px;font-weight:600;margin:0 0 10px}\n.sp-lede{margin:4px 0 0;color:var(--ink2);font-size:13.5px;max-width:720px}\n.sp-head-actions{display:flex;gap:8px;flex-wrap:wrap}\n\n/* buttons */\n.sp-btn{height:34px;border:1px solid #cfd4da;background:var(--paper);color:var(--ink);border-radius:6px;padding:0 12px;font:500 13px var(--sans);cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:6px;text-decoration:none!important;white-space:nowrap}\n.sp-btn:hover{background:#f7f8fa;border-color:#b9c0c8;color:var(--ink)}\n.sp-btn:disabled{opacity:.45;cursor:not-allowed}\n.sp-icon{width:34px;padding:0}\n.sp-primary{background:var(--brand);border-color:var(--brand);color:#fff}\n.sp-primary:hover{background:var(--brand-dark);border-color:var(--brand-dark);color:#fff}\n.sp-block{width:100%;height:40px;font-size:14px}\n.sp-link{border:0;background:none;color:#1f4fbf;font:500 12px var(--sans);cursor:pointer;padding:0}\n\n/* summary band: figures + ageing */\n.sp-summary{background:var(--paper);border:1px solid var(--rule);border-radius:8px;margin-bottom:18px}\n.sp-figs{display:grid;grid-template-columns:1.4fr 1fr 1fr 1fr}\n.sp-fig{padding:16px 20px;display:flex;flex-direction:column;gap:2px;border-left:1px solid var(--rule2)}\n.sp-fig:first-child{border-left:0}\n.sp-fig span{font-size:12px;color:var(--ink2);font-weight:500}\n.sp-fig b{font:600 22px var(--sans);font-variant-numeric:tabular-nums;letter-spacing:-.01em}\n.sp-fig small{font-size:12px;color:var(--ink3)}\n.sp-fig-lead b{font-size:30px;color:var(--ink);letter-spacing:-.02em}\n.sp-fig-lead span{color:var(--brand-text);font-weight:600}\n.sp-ageing{border-top:1px solid var(--rule2);padding:12px 20px 14px}\n.sp-ageing-head{display:flex;justify-content:space-between;align-items:center;font-size:12px;color:var(--ink2);font-weight:500;margin-bottom:8px}\n.sp-ageing-bar{display:flex;height:10px;border-radius:5px;overflow:hidden;background:var(--rule2);gap:2px}\n.sp-ageing-bar button{border:0;padding:0;cursor:pointer;min-width:6px;transition:opacity .15s}\n.sp-ageing-bar.filtered button:not(.on){opacity:.25}\n.sp-ageing-keys{display:flex;gap:6px 20px;flex-wrap:wrap;margin-top:9px}\n.sp-key{border:0;background:none;padding:2px 0;cursor:pointer;display:inline-flex;align-items:center;gap:7px;font:400 12.5px var(--sans);color:var(--ink2)}\n.sp-key i{width:9px;height:9px;border-radius:2px;display:inline-block}\n.sp-key b{font:600 12.5px var(--sans);font-variant-numeric:tabular-nums;color:var(--ink)}\n.sp-key.on{color:var(--ink);text-decoration:underline;text-underline-offset:3px}\n.sp-key:disabled{cursor:default;opacity:.55}\n\n/* layout */\n.sp-main{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:18px;align-items:start;margin-bottom:18px}\n.sp-panel{background:var(--paper);border:1px solid var(--rule);border-radius:8px;overflow:hidden}\n.sp-panel-head{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;padding:14px 16px;border-bottom:1px solid var(--rule)}\n.sp-note{margin:2px 0 0;font-size:12.5px;color:var(--ink3)}\n.sp-search{display:flex;align-items:center;gap:8px;height:34px;border:1px solid #cfd4da;border-radius:6px;padding:0 10px;color:var(--ink3);min-width:240px}\n.sp-search input{border:0;outline:0;flex:1;font:400 13px var(--sans);color:var(--ink);background:transparent;min-width:0}\n\n/* tables */\n.sp-scroll{overflow-x:auto}\n.sp-table{width:100%;border-collapse:collapse;font-size:13px}\n.sp-table th{text-align:left;font-size:11.5px;color:var(--ink2);font-weight:500;padding:9px 12px;border-bottom:1px solid var(--rule);white-space:nowrap;background:#fafbfc}\n.sp-table td{padding:10px 12px;border-bottom:1px solid var(--rule2);vertical-align:middle}\n.sp-table tbody tr:last-child td{border-bottom:0}\n.sp-table .r{text-align:right;white-space:nowrap}\n.sp-table .c{width:40px;text-align:center;padding-right:0}\n.sp-table input[type=checkbox]{width:15px;height:15px;accent-color:var(--brand);cursor:pointer;vertical-align:middle}\n.sp-row:hover td{background:#fafbfc}\n.sp-row.on td{background:#f6f8fb}\n.sp-who{display:flex;align-items:center;gap:8px}\n.sp-caret{width:22px;height:22px;flex:none;border:0;border-radius:4px;background:transparent;color:var(--ink3);cursor:pointer;display:grid;place-items:center;transition:transform .15s}\n.sp-caret:hover{background:var(--rule2);color:var(--ink)}\n.sp-caret.open{transform:rotate(90deg)}\n.sp-name{font-weight:600;color:var(--ink);white-space:nowrap}\n.sp-sub{display:block;font-size:11.5px;color:var(--ink3)}\n.sp-sub.mono{font-family:var(--mono)}\n.sp-amt{font:500 13.5px var(--sans);font-variant-numeric:tabular-nums}\n.sp-total{font:600 14px var(--sans);font-variant-numeric:tabular-nums}\n.sp-age{display:inline-flex;align-items:center;gap:6px;font-size:12.5px;white-space:nowrap}\n.sp-age i{width:8px;height:8px;border-radius:2px;display:inline-block}\n.sp-nobank{color:var(--warn);font-weight:500}\n.sp-empty{text-align:center;color:var(--ink2);padding:36px 16px!important}\n\n/* expanded: the documents behind a row */\n.sp-doc td{background:#fafbfc;padding-top:7px;padding-bottom:7px;font-size:12.5px;border-bottom:1px solid var(--rule2)}\n.sp-doc td:first-child{box-shadow:none}\n.sp-tag{display:inline-block;font:500 10.5px var(--sans);letter-spacing:.02em;padding:1px 6px;border-radius:3px;border:1px solid var(--rule);color:var(--ink2);background:var(--paper);margin-right:8px;vertical-align:1px}\n.sp-doclinks{display:inline-flex;gap:12px}\n\n/* payment run */\n.sp-run{position:sticky;top:16px}\n.sp-run-head{padding:16px 18px 12px;border-bottom:1px dashed var(--rule)}\n.sp-run-total{display:block;font:600 28px var(--sans);font-variant-numeric:tabular-nums;letter-spacing:-.02em;margin-top:6px}\n.sp-run-list{list-style:none;margin:0;padding:0;max-height:380px;overflow:auto}\n.sp-run-list li{padding:10px 18px;border-bottom:1px solid var(--rule2);display:grid;grid-template-columns:1fr auto;gap:4px 10px;align-items:center}\n.sp-run-list li .sp-amt{text-align:right}\n.sp-run-list input{grid-column:1/-1;height:30px;border:1px solid #cfd4da;border-radius:5px;padding:0 8px;font:400 12.5px var(--sans);color:var(--ink);background:var(--paper);width:100%}\n.sp-run-list .sp-x{border:0;background:none;color:var(--ink3);cursor:pointer;font-size:12px;padding:0;justify-self:start}\n.sp-run-list .sp-x:hover{color:var(--ink)}\n.sp-run-form{padding:14px 18px 4px;display:flex;flex-direction:column;gap:10px}\n.sp-run-form label{display:flex;flex-direction:column;gap:4px;font-size:12px;font-weight:500;color:var(--ink2)}\n.sp-run-form select,.sp-run-form input{height:34px;border:1px solid #cfd4da;border-radius:6px;padding:0 9px;font:400 13px var(--sans);color:var(--ink);background:var(--paper);width:100%}\n\n.sp-run-actions{padding:12px 18px 16px;display:flex;flex-direction:column;gap:8px}\n.sp-hint{margin:0;font-size:11.5px;color:var(--ink3);line-height:1.45}\n.sp-warn{margin:12px 18px 0;padding:8px 10px;border-radius:6px;background:#fff7e8;color:var(--warn);font-size:12px}\n\n/* dialogs */\n.sp-modal{position:fixed;inset:0;background:rgba(21,25,30,.45);display:flex;align-items:center;justify-content:center;z-index:1050;padding:16px}\n.sp-dialog{background:var(--paper);border-radius:10px;max-width:560px;width:100%;padding:22px;box-shadow:0 24px 60px rgba(0,0,0,.25);font-size:14px;line-height:1.5;max-height:85vh;overflow:auto}\n.sp-dialog.sp-wide{max-width:900px;max-height:92vh}\n.sp-dialog table{width:100%;border-collapse:collapse;font-size:13px;margin:8px 0}\n.sp-dialog td{padding:6px 0;border-bottom:1px solid var(--rule2)}\n.sp-mfoot{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}\n.sp-photo{background:var(--canvas);border-radius:8px;display:flex;justify-content:center;align-items:center;min-height:200px;overflow:auto;max-height:70vh}\n.sp-photo img{max-width:100%;max-height:70vh;object-fit:contain;display:block}\n.sp-pdf{width:100%;height:70vh;border:0;border-radius:8px;background:var(--canvas)}\n.sp-bad{color:var(--brand-text);font-weight:500}\n\n@media (max-width:1080px){.sp-main{grid-template-columns:1fr}.sp-run{position:static}}\n@media (max-width:760px){.sp-figs{grid-template-columns:1fr 1fr}.sp-fig:nth-child(3){border-left:0}.sp-fig:nth-child(n+3){border-top:1px solid var(--rule2)}.sp{padding:16px 14px 48px}.sp-search{min-width:0;width:100%}}\n@media (prefers-reduced-motion:reduce){.sp *{transition:none!important}}\n'}
FP_OLD = '        claims = []\n        if kind == "Bill":\n            claims = frappe.get_all("Expense Claim", filters={"employee": emp, "custom_running": 1, "docstatus": 0}, fields=["name"], limit=1)\n        elif len(month) == 7:\n            claims = frappe.get_all("Expense Claim", filters={"employee": emp, "remark": ["like", "Field TA/DA % " + month], "docstatus": ["<", 2]}, fields=["name"], limit=1)\n        if claims:\n            frappe.get_doc({\n                "doctype": "Comment",\n                "comment_type": "Comment",\n                "reference_doctype": "Expense Claim",\n                "reference_name": claims[0].name,\n                "content": "Bill refused (" + kind + ", " + str(bdate or "no date") + ", Rs " + str(amount) + "): " + block["text"] + " See Bill Fingerprint " + block["name"] + ".",\n            }).insert(ignore_permissions=True)\n'
FP_NEW = '        target = None\n        ref = "Expense Claim"\n        if kind == "Bill":\n            # a settlement bill (23 Nov 2026: its own doctype): the comment goes on it\n            ref = "Settlement Expense"\n            if trip and frappe.db.exists("Settlement Expense", trip):\n                target = trip\n        elif len(month) == 7:\n            target = frappe.db.get_value("Expense Claim", {"employee": emp, "remark": ["like", "Field TA/DA % " + month], "docstatus": ["<", 2]}, "name")\n        if target:\n            frappe.get_doc({\n                "doctype": "Comment",\n                "comment_type": "Comment",\n                "reference_doctype": ref,\n                "reference_name": target,\n                "content": "Bill refused (" + kind + ", " + str(bdate or "no date") + ", Rs " + str(amount) + "): " + block["text"] + " See Bill Fingerprint " + block["name"] + ".",\n            }).insert(ignore_permissions=True)\n'

bad = []
# no strftime: the console's safe_exec has no __import__ (23 Nov 2026) -- "2026-11-23 18:05:12.3" -> "20261123-1805"
stamp = str(frappe.utils.now())[:16].replace("-", "").replace(":", "").replace(" ", "-")

# 1. the doctype
if frappe.db.exists("DocType", DT["name"]):
    print("DocType Settlement Expense exists")
else:
    print(W + "create DocType Settlement Expense (" + str(len(DT["fields"])) + " fields)")
    if not DRY:
        frappe.get_doc(DT).insert(ignore_permissions=True)

# 2 + 3. the API scripts (a backup of each first, as a private File on the script)
for pair in [["Settlement API", API_SRC], ["Settlement Accounts API", ACC_SRC]]:
    if not frappe.db.exists("Server Script", pair[0]):
        bad.append("no Server Script " + pair[0])
        continue
    old = frappe.db.get_value("Server Script", pair[0], "script") or ""
    if old == pair[1]:
        print("already in: " + pair[0])
        continue
    print(W + "replace Server Script " + pair[0] + " (" + str(len(old)) + " -> " + str(len(pair[1])) + " characters)")
    if not DRY:
        frappe.get_doc({"doctype": "File", "file_name": pair[0].lower().replace(" ", "-") + "-before-split-" + stamp + ".py", "content": old,
                        "is_private": 1, "attached_to_doctype": "Server Script", "attached_to_name": pair[0]}).insert(ignore_permissions=True)
        s = frappe.get_doc("Server Script", pair[0])
        s.script = pair[1]
        s.disabled = 0
        s.save(ignore_permissions=True)

# 4. the report
if frappe.db.exists("Report", "Settlement To Pay"):
    rp = frappe.db.get_value("Report", "Settlement To Pay", ["report_script", "ref_doctype"], as_dict=True)
    if rp.report_script == REPORT_SRC and rp.ref_doctype == "Settlement Expense":
        print("already in: Report Settlement To Pay")
    else:
        print(W + "update Report Settlement To Pay (ref " + str(rp.ref_doctype) + " -> Settlement Expense)")
        if not DRY:
            frappe.db.set_value("Report", "Settlement To Pay", {"report_script": REPORT_SRC, "ref_doctype": "Settlement Expense"})
else:
    bad.append("no Report Settlement To Pay (the page's Excel button opens it) -- run settlement_booking_console.py first")

# 5. the page
pg = frappe.db.get_value("Web Page", {"route": "settlement-payments"}, "name")
if not pg:
    bad.append("no Web Page /settlement-payments -- run settlement_payments_dashboard_console.py first")
else:
    d = frappe.get_doc("Web Page", pg)
    if d.javascript == PAGE["javascript"] and d.main_section_html == PAGE["main_section_html"] and d.css == PAGE["css"]:
        print("already in: Web Page " + pg)
    else:
        print(W + "update Web Page " + pg + " (bills link to Settlement Expense + Journal Entry)")
        if not DRY:
            d.main_section_html = PAGE["main_section_html"]
            d.javascript = PAGE["javascript"]
            d.css = PAGE["css"]
            d.insert_style = 1
            d.save(ignore_permissions=True)

# 6. the fingerprint register
fp = frappe.db.get_value("Server Script", "Bill Fingerprint API", "script") or ""
if FP_NEW in fp:
    print("already in: Bill Fingerprint API")
elif fp.count(FP_OLD) != 1:
    bad.append("Bill Fingerprint API: the part to change is not as expected -- not changed (settlement still works; a refused bill just gets no comment)")
else:
    print(W + "patch Server Script Bill Fingerprint API (refused settlement bill -> comment on the bill)")
    if not DRY:
        frappe.get_doc({"doctype": "File", "file_name": "bill-fingerprint-api-before-split-" + stamp + ".py", "content": fp,
                        "is_private": 1, "attached_to_doctype": "Server Script", "attached_to_name": "Bill Fingerprint API"}).insert(ignore_permissions=True)
        s = frappe.get_doc("Server Script", "Bill Fingerprint API")
        s.script = fp.replace(FP_OLD, FP_NEW)
        s.save(ignore_permissions=True)

# 7. the two settlement test claims
for nm in ["HR-EXP-2026-00026", "HR-EXP-2026-00025"]:
    c = frappe.db.get_value("Expense Claim", nm, ["name", "employee_name", "docstatus", "total_claimed_amount", "remark", "custom_running"], as_dict=True)
    if not c:
        print(nm + ": already gone")
        continue
    test = (str(c.remark or "").startswith("Settlement SR-") or c.custom_running)
    print(("WILL " if CLEAN_TEST else "would (CLEAN_TEST) ") + ("cancel + delete " if c.docstatus == 1 else "delete ") + nm
          + " (" + str(c.employee_name) + ", Rs " + str(c.total_claimed_amount) + ", " + ("booked settlement" if c.docstatus == 1 else "running draft") + ")"
          + ("" if test else "  -- NOT a settlement claim, left alone"))
    if CLEAN_TEST and test and not DRY:
        for sr in frappe.get_all("Settlement Request", filters={"booked": nm}, pluck="name"):
            frappe.db.set_value("Settlement Request", sr, "booked", None)
        for sr in frappe.get_all("Settlement Request", filters={"claim": nm}, pluck="name"):
            frappe.db.set_value("Settlement Request", sr, "claim", None)
        doc = frappe.get_doc("Expense Claim", nm)
        if doc.docstatus == 1:
            doc.flags.ignore_permissions = True
            doc.cancel()
        frappe.delete_doc("Expense Claim", nm, ignore_permissions=True, force=True)

print("")
if bad:
    print("PROBLEMS:")
    for x in bad:
        print("   " + x)
print("dry run -- nothing changed." if DRY else "done.")
